import { readdir } from "node:fs/promises";
import { join, relative } from "node:path";
import { spawnSync } from "node:child_process";

const repoRoot = join(import.meta.dirname, "..");

async function listJavaScriptFiles(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = await Promise.all(entries.map(async (entry) => {
    const fullPath = join(dir, entry.name);
    if (entry.isDirectory()) {
      return listJavaScriptFiles(fullPath);
    }
    return entry.isFile() && /\.(mjs|js)$/.test(entry.name) ? [fullPath] : [];
  }));
  return files.flat();
}

const sourceFiles = [
  ...(await listJavaScriptFiles(join(repoRoot, "src"))),
  ...(await listJavaScriptFiles(join(repoRoot, "scripts")))
];

let hasError = false;

for (const file of sourceFiles) {
  const result = spawnSync(process.execPath, ["--check", file], {
    cwd: repoRoot,
    stdio: "inherit"
  });

  if (result.status !== 0) {
    hasError = true;
    console.error(`Syntax check failed: ${relative(repoRoot, file)}`);
  }
}

if (hasError) {
  process.exit(1);
}

// ==UserScript==
// @name         AniList BTVA Connector
// @namespace    https://github.com/ceeprus
// @version      1.0.13
// @description  Swap a voice actor's AniList roles for their Behind The Voice Actors roles: games, dubs, movies and more
// @icon         https://www.google.com/s2/favicons?sz=64&domain=anilist.co
// @author       ceeprus
// @license      MIT
// @match        https://anilist.co/*
// @grant        GM_xmlhttpRequest
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_listValues
// @grant        GM_deleteValue
// @connect      www.behindthevoiceactors.com
// @run-at       document-idle
// @downloadURL  https://raw.githubusercontent.com/ceeprus/userscript/main/anilist/anilist-btva-connector.user.js
// @updateURL    https://raw.githubusercontent.com/ceeprus/userscript/main/anilist/anilist-btva-connector.user.js
