    function parse(toks, i, opts) {
      var out = '', guard = 0;
      for (; i.p < toks.length;) {
        if (++guard > toks.length * 4 + 100) break;
        var tk = toks[i.p];
        if (tk.t === 'text') { out += opts.inLink ? textToHtml(tk.v) : autoLink(textToHtml(tk.v)); i.p++; continue; }
        if (tk.t === 'star') { i.p++; continue; }
