              cells += '<' + cell + '>' + parseUntilClose(toks, i, cell, opts).replace(/^(<br>)+|(<br>)+$/g, '') + '</' + cell + '>';
            } else i.p++;
          }
          rows += '<tr>' + cells + '</tr>';
        } else i.p++;
