      e.preventDefault();
      collapsedTab.onclick();
    };
    document.body.appendChild(collapsedTab);

    setWidth(store.get(K_W, DEFAULT_W));
    wireResize(grip);
    if (store.get(K_COLLAPSED, false)) setCollapsed(true, true);
    positionTab();
  }

  function setWidth(w) {
    w = Math.max(MIN_W, Math.min(MAX_W, w | 0));
