(function () {
    'use strict';

    const IG_APP_ID = '936619743392459';
    const ENABLE_EXIF = true;
    const RESERVED_SEGMENTS = new Set(['audio', 'videos', 'comments', 'liked_by', 'explore', 'reels', 'reel', 'p']);
    const mediaByCode = new Map();
    const mediaById = new Map();
    const userByName = new Map();
    const storyTrays = new Map();

    let savedVolume = typeof GM_getValue === 'function' ? GM_getValue('ig_clean_volume', 1) : 1;

    // -------------------------------------------------------------------------
    // 1. Media Extractors & Merging (Highest Quality Always)
    // -------------------------------------------------------------------------
    function pickBestImage(item) {
        const candidates = item?.image_versions2?.candidates;
        if (Array.isArray(candidates) && candidates.length) {
            const sorted = [...candidates]
                .filter(c => c?.url)
                .sort((a, b) => ((b.width || 0) * (b.height || 0)) - ((a.width || 0) * (a.height || 0)));
            if (sorted[0]?.url) return sorted[0].url;
        }
        return item?.display_url || item?.display_resources?.at(-1)?.src || null;
    }

    function pickBestVideoFromDash(manifestXml) {
        if (!manifestXml || typeof manifestXml !== 'string') return null;
        try {
            const doc = new DOMParser().parseFromString(manifestXml, 'application/xml');
            const reps = [...doc.querySelectorAll('AdaptationSet[contentType="video"] Representation, Representation[mimeType^="video"]')];
            let bestUrl = null;
            let bestScore = -1;
            for (const rep of reps) {
                const base = rep.querySelector('BaseURL')?.textContent?.trim();
                if (!base) continue;
                const w = parseInt(rep.getAttribute('width') || '0', 10);
                const h = parseInt(rep.getAttribute('height') || '0', 10);
                const bw = parseInt(rep.getAttribute('bandwidth') || '0', 10);
                const score = (w * h * 1000000) + bw;
                if (score > bestScore) {
                    bestScore = score;
                    bestUrl = base;
                }
            }
            return bestUrl;
        } catch (_) {
            return null;
        }
    }

    function pickBestVideo(item) {
        if (!item) return null;
        const versions = item.video_versions;
        if (Array.isArray(versions) && versions.length) {
            const sorted = [...versions]
                .filter(v => v?.url)
                .sort((a, b) => ((b.width || 0) * (b.height || 0)) - ((a.width || 0) * (a.height || 0)));
            if (sorted[0]?.url) return sorted[0].url;
        }
        return (
            item.playable_url_quality_hd ||
            item.video_url ||
            item.playable_url ||
            item.video_resources?.at(-1)?.src ||
            pickBestVideoFromDash(item.video_dash_manifest) ||
            null
        );
    }

    function pickBestAvatar(user) {
        if (user?.hd_profile_pic_url_info?.url) return user.hd_profile_pic_url_info.url;
        if (Array.isArray(user?.hd_profile_pic_versions) && user.hd_profile_pic_versions.length) {
            const sorted = [...user.hd_profile_pic_versions]
                .filter(v => v?.url)
                .sort((a, b) => ((b.width || 0) * (b.height || 0)) - ((a.width || 0) * (a.height || 0)));
            if (sorted[0]?.url) return sorted[0].url;
        }
        return user?.profile_pic_url_hd || user?.profile_pic_url || null;
    }

    function maxMediaArea(list) {
        if (!Array.isArray(list) || !list.length) return 0;
        return Math.max(...list.map(c => (c?.width || 0) * (c?.height || 0)));
    }

    function mergeMediaEntry(map, key, incoming) {
        const existing = map.get(key);
        if (!existing) {
            map.set(key, incoming);
            return;
        }
        const merged = { ...existing, ...incoming };
        const existingVidArea = maxMediaArea(existing.video_versions);
        const incomingVidArea = maxMediaArea(incoming.video_versions);
        if (existingVidArea > incomingVidArea || (!incoming.video_versions?.length && existing.video_versions?.length)) {
            merged.video_versions = existing.video_versions;
        }
        if (!incoming.video_url && existing.video_url) merged.video_url = existing.video_url;
        if (!incoming.playable_url_quality_hd && existing.playable_url_quality_hd) merged.playable_url_quality_hd = existing.playable_url_quality_hd;
        if (!incoming.video_dash_manifest && existing.video_dash_manifest) merged.video_dash_manifest = existing.video_dash_manifest;
        if (!incoming.carousel_media?.length && existing.carousel_media?.length) merged.carousel_media = existing.carousel_media;

        const existingImgArea = maxMediaArea(existing.image_versions2?.candidates);
        const incomingImgArea = maxMediaArea(incoming.image_versions2?.candidates);
        if (
            existingImgArea > incomingImgArea ||
            (existingImgArea === incomingImgArea && (existing.image_versions2?.candidates?.length || 0) > (incoming.image_versions2?.candidates?.length || 0))
        ) {
            merged.image_versions2 = existing.image_versions2;
        }
        map.set(key, merged);
    }

    function indexMediaObject(obj, depth = 0, seen = new WeakSet()) {
        if (!obj || typeof obj !== 'object' || depth > 14) return;
        if (seen.has(obj)) return;
        seen.add(obj);

        if (obj.username && (obj.hd_profile_pic_url_info || obj.hd_profile_pic_versions || obj.profile_pic_url_hd || obj.profile_pic_url)) {
            userByName.set(String(obj.username).toLowerCase(), obj);
        }

        if (Array.isArray(obj.items) && obj.items.length > 0 && (obj.id || obj.user?.username)) {
            const trayKey = obj.id ? String(obj.id) : null;
            const uname = obj.user?.username ? String(obj.user.username).toLowerCase() : null;
            if (trayKey) storyTrays.set(trayKey, obj.items);
            if (uname) storyTrays.set(uname, obj.items);
        }

        if (obj.image_versions2 || obj.video_versions || obj.carousel_media || obj.display_url || obj.video_url || obj.playable_url_quality_hd || obj.video_dash_manifest) {
            const code = obj.code || obj.shortcode;
            const id = obj.pk ? String(obj.pk) : (obj.id ? String(obj.id).split('_')[0] : null);
            if (code) mergeMediaEntry(mediaByCode, code, obj);
            if (id) mergeMediaEntry(mediaById, id, obj);

            if (Array.isArray(obj.carousel_media)) {
                obj.carousel_media.forEach(slide => indexMediaObject(slide, depth + 1, seen));
            }
        }

        if (Array.isArray(obj)) {
            for (const item of obj) indexMediaObject(item, depth + 1, seen);
        } else {
            for (const key of Object.keys(obj)) {
                if (key === 'return' || key === 'child' || key === 'sibling' || key === '_owner' || key === 'stateNode') continue;
                const val = obj[key];
                if (val && typeof val === 'object') indexMediaObject(val, depth + 1, seen);
            }
        }
    }

    function safeParseAndIndex(text) {
        if (!text || typeof text !== 'string') return;
        const cleaned = text.startsWith('for (;;);') ? text.slice(9) : text;
        if (!cleaned.startsWith('{') && !cleaned.startsWith('[')) return;
        try {
            indexMediaObject(JSON.parse(cleaned));
        } catch (_) {}
    }

    const pageWin = typeof unsafeWindow !== 'undefined' ? unsafeWindow : window;

    const origFetch = pageWin.fetch;
    if (typeof origFetch === 'function') {
        pageWin.fetch = async function (...args) {
            const res = await origFetch.apply(this, args);
            try {
                const url = typeof args[0] === 'string' ? args[0] : args[0]?.url || '';
                if (url.includes('instagram.com') && (url.includes('graphql') || url.includes('/api/v1/'))) {
                    res.clone().text().then(safeParseAndIndex).catch(() => {});
                }
            } catch (_) {}
            return res;
        };
    }

    const origOpen = pageWin.XMLHttpRequest.prototype.open;
    const origSend = pageWin.XMLHttpRequest.prototype.send;
    pageWin.XMLHttpRequest.prototype.open = function (method, url) {
        this._igUrl = url || '';
        return origOpen.apply(this, arguments);
    };
    pageWin.XMLHttpRequest.prototype.send = function () {
        this.addEventListener('load', function () {
            try {
                if (this._igUrl && (this._igUrl.includes('graphql') || this._igUrl.includes('/api/v1/'))) {
                    safeParseAndIndex(this.responseText);
                }
            } catch (_) {}
        });
        return origSend.apply(this, arguments);
    };

    function scanEmbeddedScripts() {
        document.querySelectorAll('script[type="application/json"]').forEach(s => {
            if (s.dataset.igScanned) return;
            s.dataset.igScanned = '1';
            safeParseAndIndex(s.textContent);
        });
    }

    // -------------------------------------------------------------------------
    // 2. React Fiber Extraction (Zero Network Calls)
    // -------------------------------------------------------------------------
    function findMediaInReactFiber(el, targetCode) {
        if (!el) return null;
        const candidates = [el, el.querySelector('video'), el.querySelector('img')].filter(Boolean);
        let bestMatch = null;

        for (const node of candidates) {
            const fiberKey = Object.keys(node).find(k => k.startsWith('__reactFiber$') || k.startsWith('__reactInternalInstance$'));
            if (!fiberKey) continue;

            let fiber = node[fiberKey];
            let steps = 0;
            while (fiber && steps < 50) {
                const props = fiber.memoizedProps;
                if (props && typeof props === 'object') {
                    indexMediaObject(props, 0);
                    if (targetCode && mediaByCode.has(targetCode)) {
                        const hit = mediaByCode.get(targetCode);
                        if (pickBestVideo(hit) || pickBestImage(hit)) bestMatch = hit;
                    }
                    const direct = props.media || props.clips_item || props.item || props.post || props.shortcode_media;
                    if (direct && typeof direct === 'object' && (pickBestVideo(direct) || pickBestImage(direct))) {
                        if (!targetCode || direct.code === targetCode || direct.shortcode === targetCode) {
                            return direct;
                        }
                        if (!bestMatch) bestMatch = direct;
                    }
                }
                fiber = fiber.return;
                steps++;
            }
        }
        return bestMatch;
    }

    function findStoryTrayInReactFiber(el) {
        if (!el) return null;
        const candidates = [el, el.querySelector('video'), el.querySelector('img')].filter(Boolean);
        for (const node of candidates) {
            const fiberKey = Object.keys(node).find(k => k.startsWith('__reactFiber$') || k.startsWith('__reactInternalInstance$'));
            if (!fiberKey) continue;
            let fiber = node[fiberKey];
            let steps = 0;
            while (fiber && steps < 50) {
                const props = fiber.memoizedProps;
                if (props && typeof props === 'object') {
                    const tray = props.reel?.items || props.story?.items || props.items;
                    if (Array.isArray(tray) && tray.length > 0 && (tray[0]?.image_versions2 || tray[0]?.video_versions)) {
                        return tray;
                    }
                }
                fiber = fiber.return;
                steps++;
            }
        }
        return null;
    }

    // -------------------------------------------------------------------------
    // 3. API Fallbacks (with CSRF Token)
    // -------------------------------------------------------------------------
    function getCookie(name) {
        const m = document.cookie.match(new RegExp('(?:^|; )' + name + '=([^;]*)'));
        return m ? decodeURIComponent(m[1]) : '';
    }

    function getIgHeaders() {
        const headers = { 'x-ig-app-id': IG_APP_ID };
        const csrf = getCookie('csrftoken');
        if (csrf) headers['x-csrftoken'] = csrf;
        return headers;
    }

    function shortcodeToId(shortcode) {
        if (!shortcode) return null;
        const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
        let id = 0n;
        for (const ch of shortcode.trim()) {
            const idx = alphabet.indexOf(ch);
            if (idx === -1) return null;
            id = id * 64n + BigInt(idx);
        }
        return id.toString();
    }

    async function fetchMediaInfoFallback(shortcode) {
        const mediaId = shortcodeToId(shortcode);
        if (mediaId) {
            try {
                const res = await pageWin.fetch(`/api/v1/media/${mediaId}/info/`, {
                    credentials: 'include',
                    headers: getIgHeaders()
                });
                if (res.ok) {
                    const data = await res.json();
                    indexMediaObject(data);
                    const found = data?.items?.[0] || mediaByCode.get(shortcode) || mediaById.get(mediaId);
                    if (found) return found;
                }
            } catch (_) {}
        }

        try {
            const res = await pageWin.fetch(`/p/${encodeURIComponent(shortcode)}/?__a=1&__d=dis`, {
                credentials: 'include',
                headers: getIgHeaders()
            });
            if (res.ok) {
                const text = await res.text();
                safeParseAndIndex(text);
                if (mediaByCode.has(shortcode)) return mediaByCode.get(shortcode);
            }
        } catch (_) {}

        return mediaByCode.get(shortcode) || null;
    }

    async function fetchUserProfileFallback(username) {
        try {
            const res = await pageWin.fetch(`/api/v1/users/web_profile_info/?username=${encodeURIComponent(username)}`, {
                credentials: 'include',
                headers: getIgHeaders()
            });
            if (!res.ok) return null;
            const data = await res.json();
            const user = data?.data?.user;
            if (user) {
                indexMediaObject(user);
                if (user.id) {
                    const infoRes = await pageWin.fetch(`/api/v1/users/${user.id}/info/`, {
                        credentials: 'include',
                        headers: getIgHeaders()
                    }).catch(() => null);
                    if (infoRes?.ok) {
                        const infoJson = await infoRes.json();
                        if (infoJson?.user) indexMediaObject(infoJson.user);
                        return infoJson?.user || user;
                    }
                }
            }
            return user || null;
        } catch (_) {
            return null;
        }
    }

    async function fetchStoryTrayFallback(reelIdOrUsername) {
        try {
            let reelId = reelIdOrUsername;
            if (reelId && !/^(highlight:)?\d+$/.test(reelId)) {
                const user = userByName.get(reelId.toLowerCase()) || await fetchUserProfileFallback(reelId);
                reelId = user?.id || user?.pk || null;
            }
            if (!reelId) return null;
            const res = await pageWin.fetch(`/api/v1/feed/reels_media/?reel_ids=${encodeURIComponent(reelId)}`, {
                credentials: 'include',
                headers: getIgHeaders()
            });
            if (!res.ok) return null;
            const data = await res.json();
            indexMediaObject(data);
            const tray = data?.reels?.[reelId]?.items || data?.reels_media?.[0]?.items || null;
            return Array.isArray(tray) ? tray : null;
        } catch (_) {
            return null;
        }
    }

    // -------------------------------------------------------------------------
    // 4. Download, EXIF Injection, New Tab & Date Helpers
    // -------------------------------------------------------------------------
    function getTimestampDate(item, container) {
        const ts = item?.taken_at_timestamp || item?.taken_at;
        let dateObj = ts ? new Date(ts > 1e12 ? ts : ts * 1000) : null;
        if (!dateObj || isNaN(dateObj.getTime())) {
            const dt = container?.querySelector('time[datetime]')?.getAttribute('datetime');
            if (dt) dateObj = new Date(dt);
        }
        return (dateObj && !isNaN(dateObj.getTime())) ? dateObj : null;
    }

    function formatDatePrefix(item, container) {
        const d = getTimestampDate(item, container);
        if (!d) return null;
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    }

    function formatExifDate(d) {
        if (!d) return null;
        return `${d.getFullYear()}:${String(d.getMonth() + 1).padStart(2, '0')}:${String(d.getDate()).padStart(2, '0')} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`;
    }

    function injectExifIntoJpegBlob(blob, exifMeta) {
        return new Promise((resolve) => {
            if (typeof piexif === 'undefined' || !exifMeta || !blob || !blob.size || (blob.type && !blob.type.includes('jpeg'))) {
                return resolve(blob);
            }
            const reader = new FileReader();
            reader.onload = () => {
                try {
                    const dataUrl = reader.result;
                    if (typeof dataUrl !== 'string' || !dataUrl.startsWith('data:image/jpeg')) {
                        return resolve(blob);
                    }
                    const zeroth = {};
                    const exif = {};
                    const exifStr = formatExifDate(exifMeta.date);
                    if (exifStr) {
                        zeroth[piexif.ImageIFD.DateTime] = exifStr;
                        exif[piexif.ExifIFD.DateTimeOriginal] = exifStr;
                        exif[piexif.ExifIFD.DateTimeDigitized] = exifStr;
                    }
                    if (exifMeta.username) {
                        zeroth[piexif.ImageIFD.Artist] = `@${exifMeta.username}`;
                    }
                    if (exifMeta.sourceUrl) {
                        zeroth[piexif.ImageIFD.ImageDescription] = exifMeta.sourceUrl;
                    }
                    const exifBytes = piexif.dump({ '0th': zeroth, Exif: exif });
                    const updatedDataUrl = piexif.insert(exifBytes, dataUrl);
                    const bin = atob(updatedDataUrl.split(',')[1]);
                    const arr = new Uint8Array(bin.length);
                    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
                    resolve(new Blob([arr], { type: 'image/jpeg' }));
                } catch (_) {
                    resolve(blob);
                }
            };
            reader.onerror = () => resolve(blob);
            reader.readAsDataURL(blob);
        });
    }

    function triggerBlobDownload(blob, filename) {
        // Do not pass page-scoped blob: URLs to GM_download(); background workers
        // in MV3 extensions often fail silently on them. Use a direct <a download>.
        const blobUrl = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = blobUrl;
        a.download = filename;
        a.style.display = 'none';
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(blobUrl), 15000);
    }

    function openUrlInNewTab(url) {
        if (!url) return alert('Could not find media URL.');
        if (typeof GM_openInTab === 'function') {
            GM_openInTab(url, { active: true, insert: true });
        } else {
            window.open(url, '_blank', 'noopener,noreferrer');
        }
    }

    function downloadFile(url, filename, exifMeta = null) {
        if (!url) return alert('Could not find media URL.');

        const isJpg = filename.toLowerCase().endsWith('.jpg') || filename.toLowerCase().endsWith('.jpeg');

        const directGmDownload = () => {
            if (typeof GM_download === 'function') {
                try {
                    GM_download({
                        url,
                        name: filename,
                        saveAs: false,
                        onerror: () => openUrlInNewTab(url),
                        ontimeout: () => openUrlInNewTab(url)
                    });
                    return;
                } catch (_) {}
            }
            openUrlInNewTab(url);
        };

        const fetchBlobAndSave = () => {
            GM_xmlhttpRequest({
                method: 'GET',
                url,
                responseType: 'blob',
                onload: async (res) => {
                    if (res.status >= 400 || !res.response || !res.response.size) {
                        console.warn('[IG Clean] GM_xmlhttpRequest fallback:', res.status);
                        return directGmDownload();
                    }
                    try {
                        let blob = res.response;
                        if (isJpg && exifMeta && ENABLE_EXIF) {
                            blob = await injectExifIntoJpegBlob(blob, exifMeta);
                        }
                        triggerBlobDownload(blob, filename);
                    } catch (err) {
                        console.warn('[IG Clean] Blob save error, falling back:', err);
                        directGmDownload();
                    }
                },
                onerror: (err) => {
                    console.warn('[IG Clean] GM_xmlhttpRequest error:', err);
                    directGmDownload();
                },
                ontimeout: directGmDownload
            });
        };

        if (isJpg && exifMeta && ENABLE_EXIF && typeof piexif !== 'undefined') {
            return fetchBlobAndSave();
        }

        if (typeof GM_download === 'function') {
            try {
                GM_download({
                    url,
                    name: filename,
                    saveAs: false,
                    onerror: fetchBlobAndSave,
                    ontimeout: fetchBlobAndSave
                });
                return;
            } catch (_) {}
        }
        fetchBlobAndSave();
    }

    // -------------------------------------------------------------------------
    // 5. Modals: Thumbnail Picker & Story Tagged Profiles
    // -------------------------------------------------------------------------
    function closeModals() {
        document.querySelectorAll('.ig-clean-modal-backdrop').forEach(m => m.remove());
    }

    function openPickerModal(titleText, entries) {
        closeModals();

        const backdrop = document.createElement('div');
        backdrop.className = 'ig-clean-modal-backdrop';
        backdrop.addEventListener('click', (e) => {
            if (e.target === backdrop) closeModals();
        });

        const modal = document.createElement('div');
        modal.className = 'ig-clean-modal';

        const header = document.createElement('div');
        header.className = 'ig-clean-modal-header';
        const titleSpan = document.createElement('span');
        titleSpan.textContent = `${titleText} (${entries.length})`;
        header.appendChild(titleSpan);

        const closeBtn = document.createElement('button');
        closeBtn.type = 'button';
        closeBtn.className = 'ig-clean-modal-close';
        closeBtn.textContent = '✕';
        closeBtn.addEventListener('click', closeModals);
        header.appendChild(closeBtn);

        const actions = document.createElement('div');
        actions.className = 'ig-clean-modal-actions';

        const selectAllLabel = document.createElement('label');
        selectAllLabel.className = 'ig-clean-select-all';
        const selectAllCb = document.createElement('input');
        selectAllCb.type = 'checkbox';
        selectAllCb.checked = true;
        selectAllLabel.appendChild(selectAllCb);
        selectAllLabel.appendChild(document.createTextNode(' Select All'));

        const dlSelectedBtn = document.createElement('button');
        dlSelectedBtn.type = 'button';
        dlSelectedBtn.className = 'ig-clean-modal-btn primary';
        dlSelectedBtn.textContent = 'Download Selected';

        const dlAllBtn = document.createElement('button');
        dlAllBtn.type = 'button';
        dlAllBtn.className = 'ig-clean-modal-btn';
        dlAllBtn.textContent = 'Download All';

        const dlAllVideosBtn = document.createElement('button');
        dlAllVideosBtn.type = 'button';
        dlAllVideosBtn.className = 'ig-clean-modal-btn';
        dlAllVideosBtn.textContent = 'Save All Videos';

        const dlAllThumbsBtn = document.createElement('button');
        dlAllThumbsBtn.type = 'button';
        dlAllThumbsBtn.className = 'ig-clean-modal-btn';
        dlAllThumbsBtn.textContent = 'Save All Thumbnails';

        actions.appendChild(selectAllLabel);
        actions.appendChild(dlSelectedBtn);
        actions.appendChild(dlAllBtn);
        if (entries.some(e => e.isVideo)) {
            actions.appendChild(dlAllVideosBtn);
        }
        if (entries.some(e => e.thumbUrl)) {
            actions.appendChild(dlAllThumbsBtn);
        }

        const grid = document.createElement('div');
        grid.className = 'ig-clean-modal-grid';

        const checkboxes = [];
        entries.forEach((entry, idx) => {
            const card = document.createElement('div');
            card.className = 'ig-clean-card';

            const cb = document.createElement('input');
            cb.type = 'checkbox';
            cb.className = 'ig-clean-card-cb';
            cb.checked = true;
            checkboxes.push(cb);

            const thumbWrap = document.createElement('div');
            thumbWrap.className = 'ig-clean-card-thumb';
            const img = document.createElement('img');
            img.src = entry.previewUrl || entry.thumbUrl || entry.url;
            img.loading = 'lazy';
            thumbWrap.appendChild(img);

            const badge = document.createElement('span');
            badge.className = 'ig-clean-card-badge';
            badge.textContent = entry.label || `${idx + 1} · ${entry.isVideo ? 'VID' : 'IMG'}`;
            thumbWrap.appendChild(badge);

            thumbWrap.addEventListener('click', () => {
                cb.checked = !cb.checked;
                selectAllCb.checked = checkboxes.every(c => c.checked);
            });

            const cardFooter = document.createElement('div');
            cardFooter.className = 'ig-clean-card-footer';

            const dlOne = document.createElement('button');
            dlOne.type = 'button';
            dlOne.title = 'Save Highest Quality';
            dlOne.textContent = '↓ Save';
            dlOne.addEventListener('click', () => downloadFile(entry.url, entry.filename, entry.exifMeta));

            const openOne = document.createElement('button');
            openOne.type = 'button';
            openOne.title = 'Open in New Tab';
            openOne.textContent = '↗ Tab';
            openOne.addEventListener('click', () => openUrlInNewTab(entry.url));

            cardFooter.appendChild(dlOne);
            cardFooter.appendChild(openOne);

            if (entry.isVideo && entry.thumbUrl) {
                const dlThumb = document.createElement('button');
                dlThumb.type = 'button';
                dlThumb.title = 'Save Video Thumbnail';
                dlThumb.textContent = '🖼';
                dlThumb.addEventListener('click', () => downloadFile(entry.thumbUrl, entry.thumbFilename || `${entry.filename}_thumb.jpg`, entry.exifMeta));

                const viewThumb = document.createElement('button');
                viewThumb.type = 'button';
                viewThumb.title = 'Preview Video Thumbnail in New Tab';
                viewThumb.textContent = '👁';
                viewThumb.addEventListener('click', () => openUrlInNewTab(entry.thumbUrl));

                cardFooter.appendChild(dlThumb);
                cardFooter.appendChild(viewThumb);
            }

            card.appendChild(cb);
            card.appendChild(thumbWrap);
            card.appendChild(cardFooter);
            grid.appendChild(card);
        });

        selectAllCb.addEventListener('change', () => {
            checkboxes.forEach(c => { c.checked = selectAllCb.checked; });
        });

        const batchSave = (list) => {
            list.forEach((entry, i) => {
                setTimeout(() => downloadFile(entry.url, entry.filename, entry.exifMeta), i * 450);
            });
            closeModals();
        };

        dlSelectedBtn.addEventListener('click', () => {
            const chosen = entries.filter((_, i) => checkboxes[i].checked);
            if (!chosen.length) return alert('Select at least one item.');
            batchSave(chosen);
        });
        dlAllBtn.addEventListener('click', () => batchSave(entries));
        dlAllVideosBtn.addEventListener('click', () => {
            const videoEntries = entries.filter(e => e.isVideo);
            if (!videoEntries.length) return alert('No videos found.');
            batchSave(videoEntries);
        });
        dlAllThumbsBtn.addEventListener('click', () => {
            const thumbEntries = entries
                .filter(e => e.thumbUrl || !e.isVideo)
                .map(e => ({
                    url: e.thumbUrl || e.url,
                    filename: e.isVideo ? (e.thumbFilename || `${e.filename}_thumb.jpg`) : e.filename,
                    exifMeta: e.exifMeta
                }));
            if (!thumbEntries.length) return alert('No thumbnails found.');
            batchSave(thumbEntries);
        });

        modal.appendChild(header);
        modal.appendChild(actions);
        modal.appendChild(grid);
        backdrop.appendChild(modal);
        document.body.appendChild(backdrop);
    }

    function extractTaggedProfilesFromItem(item) {
        const found = new Set();
        const scan = (obj, depth = 0) => {
            if (!obj || typeof obj !== 'object' || depth > 8) return;
            if (obj.user?.username) found.add(obj.user.username);
            if (obj.username && (obj.full_name !== undefined || obj.pk || obj.id)) found.add(obj.username);
            if (Array.isArray(obj)) {
                obj.forEach(x => scan(x, depth + 1));
            } else {
                for (const k of Object.keys(obj)) {
                    if (k === 'image_versions2' || k === 'video_versions') continue;
                    if (typeof obj[k] === 'object') scan(obj[k], depth + 1);
                }
            }
        };

        if (item) {
            const owner = item.user?.username || item.owner?.username;
            scan(item.reel_mentions);
            scan(item.story_bloks_stickers);
            scan(item.story_feed_media);
            scan(item.story_app_stickers);
            scan(item.usertags);
            if (owner) found.delete(owner);
        }
        return [...found];
    }

