    // -------------------------------------------------------------------------
    // 6. Context & Action Handlers
    // -------------------------------------------------------------------------
    function isValidShortcode(code) {
        return !!code && !RESERVED_SEGMENTS.has(code.toLowerCase()) && /^[A-Za-z0-9_-]{6,}$/.test(code);
    }

    function getShortcodeFromContainer(container) {
        const pathMatch = location.pathname.match(/\/(p|reel|reels)\/([^/?#]+)/);
        if (isValidShortcode(pathMatch?.[2])) return pathMatch[2];

        const links = container.querySelectorAll('a[href*="/p/"], a[href*="/reel/"], a[href*="/reels/"]');
        for (const a of links) {
            const href = a.getAttribute('href') || '';
            if (href.includes('/reels/audio/')) continue;
            const m = href.match(/\/(p|reel|reels)\/([^/?#]+)/);
            if (isValidShortcode(m?.[2])) return m[2];
        }
        return null;
    }

    function getVisibleSlideIndex(container) {
        const imgIdx = new URLSearchParams(location.search).get('img_index');
        if (imgIdx && /^\d+$/.test(imgIdx)) return Math.max(0, parseInt(imgIdx, 10) - 1);

        const ul = container.querySelector('ul');
        if (!ul) return 0;

        const slides = [...ul.children].filter(li => li.getBoundingClientRect().width > 64 && li.querySelector('img, video'));
        if (slides.length <= 1) return 0;

        const vpRect = ul.parentElement?.getBoundingClientRect() || container.getBoundingClientRect();
        const vpCenter = (vpRect.left + vpRect.right) / 2;

        let bestIdx = 0;
        let minDist = Infinity;
        slides.forEach((li, idx) => {
            const r = li.getBoundingClientRect();
            const dist = Math.abs(((r.left + r.right) / 2) - vpCenter);
            if (dist < minDist) {
                minDist = dist;
                bestIdx = idx;
            }
        });
        return bestIdx;
    }

    function getUsernameFromContainer(container, mediaObj) {
        if (mediaObj?.user?.username) return mediaObj.user.username;
        if (mediaObj?.owner?.username) return mediaObj.owner.username;
        const a = container.querySelector('header a[href^="/"], a[href^="/"] span[dir="auto"]');
        const txt = a?.textContent?.trim();
        return (txt && !txt.includes(' ')) ? txt : 'instagram';
    }

    async function handleAvatarAction(headerImg, openInTab = false) {
        scanEmbeddedScripts();
        const username = location.pathname.split('/').filter(Boolean)[0] || 'profile';
        let user = userByName.get(username.toLowerCase());
        let url = pickBestAvatar(user);

        if (!user?.hd_profile_pic_url_info) {
            const fetched = await fetchUserProfileFallback(username);
            url = pickBestAvatar(fetched) || url;
        }

        const finalUrl = url || headerImg?.src;
        if (openInTab) return openUrlInNewTab(finalUrl);
        downloadFile(finalUrl, `${username}_avatar.jpg`, { username, sourceUrl: `https://www.instagram.com/${username}/` });
    }

    async function handleAction(container, mode /* 'media' | 'thumb' | 'thumb_newtab' | 'all' | 'newtab' | 'tagged' */) {
        scanEmbeddedScripts();
        const isNewTab = (mode === 'newtab');
        const isThumbNewTab = (mode === 'thumb_newtab');

        // Story / Highlight handling
        if (location.pathname.startsWith('/stories/')) {
            const hlMatch = location.pathname.match(/\/stories\/highlights\/(\d+)/);
            const stMatch = location.pathname.match(/\/stories\/([^/]+)\/(\d+)/);
            const highlightId = hlMatch?.[1] ? `highlight:${hlMatch[1]}` : null;
            const storyUserFromUrl = stMatch?.[1] || null;
            const storyId = stMatch?.[2] || null;

            if (mode === 'all') {
                const trayKey = highlightId || (storyUserFromUrl ? storyUserFromUrl.toLowerCase() : null);
                let items = (trayKey ? storyTrays.get(trayKey) : null) || findStoryTrayInReactFiber(container);
                const enrich = (arr) => (arr || []).map(x => {
                    const id = x?.pk ? String(x.pk) : (x?.id ? String(x.id).split('_')[0] : null);
                    return (id && mediaById.get(id)) ? mediaById.get(id) : x;
                });
                items = enrich(items);

                const hasDomVideo = !!container.querySelector('video');
                if ((!items.length || (hasDomVideo && !items.some(i => pickBestVideo(i)))) && (highlightId || storyUserFromUrl)) {
                    const fetchedTray = await fetchStoryTrayFallback(highlightId || storyUserFromUrl);
                    if (fetchedTray?.length) items = enrich(fetchedTray);
                }
                if (!items.length) return alert('Could not find story/highlight tray items.');

                const entries = items.map((sItem, idx) => {
                    const uname = getUsernameFromContainer(container, sItem);
                    const dateStr = formatDatePrefix(sItem, container);
                    const sid = sItem.pk || sItem.id || (idx + 1);
                    const prefix = [uname, dateStr, 'story', sid].filter(Boolean).join('_');
                    const vUrl = pickBestVideo(sItem);
                    const iUrl = pickBestImage(sItem);
                    return {
                        isVideo: !!vUrl,
                        url: vUrl || iUrl,
                        thumbUrl: iUrl,
                        previewUrl: iUrl || vUrl,
                        filename: `${prefix}.${vUrl ? 'mp4' : 'jpg'}`,
                        thumbFilename: `${prefix}_thumb.jpg`,
                        exifMeta: {
                            date: getTimestampDate(sItem, container),
                            username: uname,
                            sourceUrl: location.href
                        }
                    };
                }).filter(e => e.url);

                return openPickerModal('Story / Highlight Picker', entries);
            }

            let item = (storyId ? mediaById.get(storyId) : null) || findMediaInReactFiber(container, null);

            if (mode === 'tagged') {
                if (!item && (highlightId || storyUserFromUrl)) {
                    const tray = await fetchStoryTrayFallback(highlightId || storyUserFromUrl);
                    item = tray?.find(x => String(x.pk || x.id) === String(storyId)) || tray?.[0] || item;
                }
                return openTaggedProfilesModal(extractTaggedProfilesFromItem(item));
            }

            if (!item) {
                const video = container.querySelector('video');
                const img = [...container.querySelectorAll('img')].find(i => i.getBoundingClientRect().width > 150);
                const url = (mode === 'thumb' || isThumbNewTab)
                    ? (video?.poster || img?.src)
                    : ((video?.src && !video.src.startsWith('blob:')) ? video.src : (video?.poster || img?.src));
                if (isNewTab || isThumbNewTab) return openUrlInNewTab(url);
                const ext = (mode !== 'thumb' && video?.src && !video.src.startsWith('blob:')) ? 'mp4' : 'jpg';
                return downloadFile(url, `story_${storyId || Date.now()}.${ext}`);
            }

            const username = getUsernameFromContainer(container, item);
            const dateStr = formatDatePrefix(item, container);
            const sid = storyId || item.pk || 'item';
            const prefix = [username, dateStr, 'story', sid].filter(Boolean).join('_');
            const videoUrl = pickBestVideo(item);
            const imageUrl = pickBestImage(item);
            const exifMeta = { date: getTimestampDate(item, container), username, sourceUrl: location.href };

            if (isThumbNewTab) return openUrlInNewTab(imageUrl);
            if (isNewTab) return openUrlInNewTab(videoUrl || imageUrl);
            if (mode === 'thumb') return downloadFile(imageUrl, `${prefix}_thumb.jpg`, exifMeta);
            if (videoUrl) return downloadFile(videoUrl, `${prefix}.mp4`);
            return downloadFile(imageUrl, `${prefix}.jpg`, exifMeta);
        }

        // Post / Reel handling
        const shortcode = getShortcodeFromContainer(container);
        const hasDomVideo = !!container.querySelector('video');
        let media = (shortcode ? mediaByCode.get(shortcode) : null) || findMediaInReactFiber(container, shortcode);

        const slideIndex = getVisibleSlideIndex(container);
        let activeItem = Array.isArray(media?.carousel_media)
            ? (media.carousel_media[slideIndex] || media.carousel_media[0])
            : media;

        if (shortcode && (!media || (mode !== 'thumb' && !isThumbNewTab && hasDomVideo && !pickBestVideo(activeItem)))) {
            const fetched = await fetchMediaInfoFallback(shortcode);
            if (fetched) {
                media = fetched;
                activeItem = Array.isArray(media?.carousel_media)
                    ? (media.carousel_media[slideIndex] || media.carousel_media[0])
                    : media;
            }
        }

        const username = getUsernameFromContainer(container, media);

        // Popup Visual Media & Thumbnail Picker Modal (Carousels, Single Posts, Videos & Reels)
        if (mode === 'all') {
            if (Array.isArray(media?.carousel_media) && media.carousel_media.length) {
                const entries = media.carousel_media.map((slide, idx) => {
                    const dateStr = formatDatePrefix(slide, container) || formatDatePrefix(media, container);
                    const base = [username, dateStr, shortcode, idx + 1].filter(Boolean).join('_');
                    const vUrl = pickBestVideo(slide);
                    const iUrl = pickBestImage(slide);
                    return {
                        isVideo: !!vUrl,
                        url: vUrl || iUrl,
                        thumbUrl: iUrl,
                        previewUrl: iUrl || vUrl,
                        filename: `${base}.${vUrl ? 'mp4' : 'jpg'}`,
                        thumbFilename: `${base}_thumb.jpg`,
                        exifMeta: {
                            date: getTimestampDate(slide, container) || getTimestampDate(media, container),
                            username,
                            sourceUrl: shortcode ? `https://www.instagram.com/p/${shortcode}/` : location.href
                        }
                    };
                }).filter(e => e.url);

                return openPickerModal(`Post ${shortcode || ''}`, entries);
            }

            if (activeItem) {
                const dateStr = formatDatePrefix(activeItem, container) || formatDatePrefix(media, container);
                const base = [username, dateStr, shortcode || Date.now()].filter(Boolean).join('_');
                const vUrl = pickBestVideo(activeItem);
                const iUrl = pickBestImage(activeItem);
                const exifMeta = {
                    date: getTimestampDate(activeItem, container) || getTimestampDate(media, container),
                    username,
                    sourceUrl: shortcode ? `https://www.instagram.com/p/${shortcode}/` : location.href
                };

                const entries = [];
                if (vUrl) {
                    entries.push({
                        isVideo: true,
                        label: '1 · VID',
                        url: vUrl,
                        thumbUrl: iUrl,
                        previewUrl: iUrl || vUrl,
                        filename: `${base}.mp4`,
                        thumbFilename: `${base}_thumb.jpg`,
                        exifMeta
                    });
                }
                if (iUrl) {
                    entries.push({
                        isVideo: false,
                        label: vUrl ? '2 · THUMB' : '1 · IMG',
                        url: iUrl,
                        thumbUrl: iUrl,
                        previewUrl: iUrl,
                        filename: vUrl ? `${base}_thumb.jpg` : `${base}.jpg`,
                        exifMeta
                    });
                }
                if (entries.length) {
                    return openPickerModal(`Post ${shortcode || ''}`, entries);
                }
            }

            // DOM fallback for Picker Modal
            const domVideo = container.querySelector('video');
            const domImgs = [...container.querySelectorAll('img')].filter(i => {
                const r = i.getBoundingClientRect();
                return r.width > 150 && !i.closest('header');
            });
            const base = [username, formatDatePrefix(null, container), shortcode || Date.now()].filter(Boolean).join('_');
            const entries = [];
            if (domVideo?.src && !domVideo.src.startsWith('blob:')) {
                entries.push({
                    isVideo: true,
                    label: '1 · VID',
                    url: domVideo.src,
                    thumbUrl: domVideo.poster || domImgs[0]?.src,
                    previewUrl: domVideo.poster || domImgs[0]?.src,
                    filename: `${base}.mp4`,
                    thumbFilename: `${base}_thumb.jpg`,
                    exifMeta: null
                });
            }
            const seenSrc = new Set();
            [domVideo?.poster, ...domImgs.map(i => i.src)].filter(Boolean).forEach((src) => {
                if (seenSrc.has(src)) return;
                seenSrc.add(src);
                entries.push({
                    isVideo: false,
                    label: domVideo ? 'THUMB' : `IMG ${entries.length + 1}`,
                    url: src,
                    thumbUrl: src,
                    previewUrl: src,
                    filename: `${base}${domVideo ? '_thumb' : `_${entries.length + 1}`}.jpg`,
                    exifMeta: null
                });
            });
            if (entries.length) {
                return openPickerModal(`Post ${shortcode || ''}`, entries);
            }
            return alert('Could not find post media or thumbnails.');
        }

        const dateStr = formatDatePrefix(activeItem, container) || formatDatePrefix(media, container);
        const slideTag = Array.isArray(media?.carousel_media) ? `${slideIndex + 1}` : null;
        const baseName = [username, dateStr, shortcode || Date.now(), slideTag].filter(Boolean).join('_');
        const exifMeta = {
            date: getTimestampDate(activeItem, container) || getTimestampDate(media, container),
            username,
            sourceUrl: shortcode ? `https://www.instagram.com/p/${shortcode}/` : location.href
        };

        if (activeItem) {
            const videoUrl = pickBestVideo(activeItem);
            const imageUrl = pickBestImage(activeItem);

            if (isThumbNewTab) return openUrlInNewTab(imageUrl);
            if (isNewTab) return openUrlInNewTab(videoUrl || imageUrl);
            if (mode === 'thumb') return downloadFile(imageUrl, `${baseName}_thumb.jpg`, exifMeta);
            if (videoUrl) return downloadFile(videoUrl, `${baseName}.mp4`);
            if (imageUrl) return downloadFile(imageUrl, `${baseName}.jpg`, exifMeta);
        }

        // Last-resort DOM fallback
        const video = container.querySelector('video');
        const imgs = [...container.querySelectorAll('img')].filter(i => {
            const r = i.getBoundingClientRect();
            return r.width > 150 && !i.closest('header');
        });
        const domImgUrl = imgs[0]?.src || video?.poster || null;
        const domMediaUrl = (video?.src && !video.src.startsWith('blob:')) ? video.src : domImgUrl;

        console.warn('[IG Clean] Fell back to DOM:', { shortcode, hasMedia: !!media, hasDomVideo, domMediaUrl });

        if (isThumbNewTab) return openUrlInNewTab(video?.poster || imgs[0]?.src);
        if (isNewTab) return openUrlInNewTab(domMediaUrl);
        if (mode === 'thumb') return downloadFile(video?.poster || imgs[0]?.src, `${baseName}_thumb.jpg`, exifMeta);
        if (video?.src && !video.src.startsWith('blob:')) return downloadFile(video.src, `${baseName}.mp4`);
        return downloadFile(domImgUrl, `${baseName}.jpg`, exifMeta);
    }

    // -------------------------------------------------------------------------
    // 7. Native Video Controls, Volume Memory & Auto-Skip "View Story"
    // -------------------------------------------------------------------------
    function enhanceVideo(video, container) {
        if (!video || video.dataset.igVideoEnhanced) return;
        video.dataset.igVideoEnhanced = '1';

        const applySavedVolume = () => {
            if (typeof savedVolume === 'number' && !isNaN(savedVolume)) {
                video.volume = Math.min(1, Math.max(0, savedVolume));
            }
        };
        applySavedVolume();
        video.addEventListener('play', applySavedVolume);
        video.addEventListener('loadedmetadata', applySavedVolume);

        video.addEventListener('volumechange', () => {
            if (!video.muted && typeof GM_setValue === 'function') {
                savedVolume = video.volume;
                GM_setValue('ig_clean_volume', savedVolume);
            }
        });

        const toggleVideoControls = (vid, e) => {
            e.preventDefault();
            e.stopPropagation();
            const enabling = !vid.controls;
            vid.controls = enabling;
            if (enabling) {
                vid.dataset.igOrigZ = vid.style.zIndex || '';
                vid.style.zIndex = '9998';
                vid.style.position = vid.style.position || 'relative';
            } else {
                vid.style.zIndex = vid.dataset.igOrigZ || '';
            }
        };

        video.addEventListener('contextmenu', (e) => toggleVideoControls(video, e));
        if (container && !container.dataset.igContextBound) {
            container.dataset.igContextBound = '1';
            container.addEventListener('contextmenu', (e) => {
                if (e.target.closest('.ig-clean-bar') || e.target.closest('.ig-clean-modal-backdrop')) return;
                const activeVid = [...container.querySelectorAll('video')].find(v => {
                    const r = v.getBoundingClientRect();
                    return r.width > 0 && r.height > 0 && e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
                });
                if (activeVid) toggleVideoControls(activeVid, e);
            });
        }
    }

    function autoClickViewStoryConfirm() {
        if (!location.pathname.startsWith('/stories/')) return;
        const buttons = document.querySelectorAll('section div[role="button"], section button');
        for (const btn of buttons) {
            if (btn.dataset.igAutoClicked) continue;
            const txt = (btn.textContent || '').trim().toLowerCase();
            if (txt === 'view story') {
                btn.dataset.igAutoClicked = '1';
                btn.click();
                break;
            }
        }
    }

