    const SVG_TAB = '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 3h6v6"/><path d="M10 14 21 3"/><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/></svg>';
    const SVG_TH = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.1-3.1a2 2 0 0 0-2.8 0L6 21"/></svg>';
    const SVG_EYE = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg>';
    const SVG_ALL = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 13v8l-4-4"/><path d="m12 21 4-4"/><path d="M4.4 15.3A7 7 0 1 1 15.7 8h1.8a4.5 4.5 0 0 1 2.4 8.3"/></svg>';
    const SVG_AT = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4"/><path d="M16 8v5a3 3 0 0 0 6 0v-1a10 10 0 1 0-4 8"/></svg>';

    function makeBtn(svg, title, cls, onClick) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `ig-clean-btn${cls ? ` ${cls}` : ''}`;
        btn.title = title;
        btn.innerHTML = svg;
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            onClick();
        });
        return btn;
    }

    function injectButtons(container, isStory = false) {
        if (!container) return;
        container.querySelectorAll('video').forEach(v => enhanceVideo(v, container));

        let bar = container.querySelector(':scope > .ig-clean-bar');
        if (!bar) {
            const rect = container.getBoundingClientRect();
            if (rect.width < 180 || rect.height < 180) return;

            container.dataset.igCleanAttached = '1';
            if (getComputedStyle(container).position === 'static') {
                container.style.position = 'relative';
            }

            bar = document.createElement('div');
            bar.className = `ig-clean-bar${isStory ? ' ig-clean-story' : ''}`;
            bar.appendChild(makeBtn(SVG_DL, 'Download Highest Quality', 'ig-clean-dl-btn', () => handleAction(container, 'media')));
            bar.appendChild(makeBtn(SVG_TAB, 'Open Highest Quality in New Tab', 'ig-clean-tab-btn', () => handleAction(container, 'newtab')));

            if (isStory) {
                bar.appendChild(makeBtn(SVG_AT, 'Tagged Profiles in Story', 'ig-clean-at-btn', () => handleAction(container, 'tagged')));
            }

            container.appendChild(bar);
        }

        if (!bar.querySelector('.ig-clean-all-btn')) {
            bar.appendChild(makeBtn(SVG_ALL, isStory ? 'Open Story / Highlight Picker' : 'Open Visual Media & Thumbnail Picker', 'ig-clean-all-btn', () => handleAction(container, 'all')));
        }

        if (container.querySelector('video')) {
            if (!bar.querySelector('.ig-clean-th-btn')) {
                bar.appendChild(makeBtn(SVG_TH, 'Download Thumbnail', 'ig-clean-th-btn', () => handleAction(container, 'thumb')));
            }
            if (!bar.querySelector('.ig-clean-eye-btn')) {
                bar.appendChild(makeBtn(SVG_EYE, 'Preview Thumbnail in New Tab', 'ig-clean-eye-btn', () => handleAction(container, 'thumb_newtab')));
            }
        } else {
            bar.querySelectorAll('.ig-clean-th-btn, .ig-clean-eye-btn').forEach(b => b.remove());
        }
    }

    function injectProfileAvatarButton() {
        if (!/^\/[A-Za-z0-9._]+\/?(reels|tagged|saved)?\/?$/.test(location.pathname)) return;
        const avatarImg = document.querySelector('header img[alt]');
        if (!avatarImg) return;
        const box = avatarImg.closest('span, div[role="button"], a')?.parentElement || avatarImg.parentElement;
        if (!box || box.dataset.igAvatarAttached) return;

        box.dataset.igAvatarAttached = '1';
        if (getComputedStyle(box).position === 'static') box.style.position = 'relative';

        const bar = document.createElement('div');
        bar.className = 'ig-clean-bar ig-clean-avatar';
        bar.appendChild(makeBtn(SVG_DL, 'Download HD Profile Picture', '', () => handleAvatarAction(avatarImg, false)));
        bar.appendChild(makeBtn(SVG_TAB, 'Open HD Profile Picture in New Tab', '', () => handleAvatarAction(avatarImg, true)));
        box.appendChild(bar);
    }

    function scanAndAttach() {
        scanEmbeddedScripts();
        autoClickViewStoryConfirm();
        injectProfileAvatarButton();

        document.querySelectorAll('article').forEach(art => {
            if (art.querySelector('video, img')) injectButtons(art);
        });

        document.querySelectorAll('section > main hr').forEach(hr => {
            const root = hr.parentElement?.parentElement?.parentElement?.parentElement;
            if (root && !root.querySelector('article') && !root.querySelector('.ig-clean-bar')) {
                injectButtons(root);
            }
        });

        if (location.pathname.startsWith('/reels/')) {
            document.querySelectorAll('section video').forEach(v => {
                let box = v.parentElement;
                while (box && box !== document.body) {
                    const r = box.getBoundingClientRect();
                    if (r.width >= 200 && r.height >= 320 && box.querySelector('a[href*="/reel"], button, svg')) {
                        break;
                    }
                    box = box.parentElement;
                }
                if (box && box !== document.body && !box.querySelector('video ~ video')) {
                    injectButtons(box);
                } else if (v.parentElement) {
                    injectButtons(v.parentElement);
                }
            });
        }

        if (location.pathname.startsWith('/stories/')) {
            document.querySelectorAll('section video, section img').forEach(el => {
                const r = el.getBoundingClientRect();
                if (r.width < 220 || r.height < 300) return;
                const box = el.closest('div[style][class]') || el.parentElement;
                if (box) injectButtons(box, true);
            });
        }
    }

    function initUI() {
        GM_addStyle(`
            .ig-clean-bar {
                position: absolute;
                top: 46px;
                right: 12px;
                z-index: 9999;
                display: flex;
                gap: 6px;
                pointer-events: auto;
            }
            .ig-clean-bar.ig-clean-story {
                top: 64px;
                right: 12px;
            }
            .ig-clean-bar.ig-clean-avatar {
                top: auto;
                bottom: 4px;
                right: 4px;
            }
            .ig-clean-btn {
                width: 32px;
                height: 32px;
                padding: 0;
                border: none;
                background: transparent;
                color: #fff;
                opacity: 0.8;
                display: flex;
                align-items: center;
                justify-content: center;
                cursor: pointer;
                filter: drop-shadow(0 1px 3px rgba(0, 0, 0, 0.85));
                transition: transform 0.15s ease, opacity 0.15s ease;
            }
            .ig-clean-btn:hover {
                opacity: 1;
                transform: scale(1.1);
            }
            .ig-clean-modal-backdrop {
                position: fixed;
                inset: 0;
                z-index: 999999;
                background: rgba(0, 0, 0, 0.78);
                display: flex;
                align-items: center;
                justify-content: center;
                padding: 16px;
            }
            .ig-clean-modal {
                width: 100%;
                max-width: 680px;
                max-height: 85vh;
                background: #18191c;
                color: #f5f5f5;
                border: 1px solid #2e3036;
                border-radius: 12px;
                display: flex;
                flex-direction: column;
                overflow: hidden;
                font-family: system-ui, -apple-system, sans-serif;
            }
            .ig-clean-modal.ig-clean-modal-sm {
                max-width: 360px;
            }
            .ig-clean-modal-header {
                display: flex;
                align-items: center;
                justify-content: space-between;
                padding: 12px 16px;
                border-bottom: 1px solid #2e3036;
                font-weight: 600;
                font-size: 14px;
            }
            .ig-clean-modal-close {
                background: none;
                border: none;
                color: #aaa;
                font-size: 18px;
                cursor: pointer;
            }
            .ig-clean-modal-close:hover { color: #fff; }
            .ig-clean-modal-actions {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 10px 16px;
                border-bottom: 1px solid #2e3036;
                font-size: 13px;
            }
            .ig-clean-select-all {
                margin-right: auto;
                cursor: pointer;
                user-select: none;
            }
            .ig-clean-modal-btn {
                padding: 6px 12px;
                border-radius: 6px;
                border: 1px solid #3c3f47;
                background: #26282e;
                color: #fff;
                font-size: 12px;
                cursor: pointer;
            }
            .ig-clean-modal-btn.primary {
                background: #0095f6;
                border-color: #0095f6;
            }
            .ig-clean-modal-grid {
                padding: 14px;
                overflow-y: auto;
                display: grid;
                grid-template-columns: repeat(auto-fill, minmax(135px, 1fr));
                gap: 12px;
            }
            .ig-clean-card {
                position: relative;
                background: #22242a;
                border-radius: 8px;
                overflow: hidden;
                border: 1px solid #32353d;
            }
            .ig-clean-card-cb {
                position: absolute;
                top: 6px;
                left: 6px;
                z-index: 2;
                width: 16px;
                height: 16px;
                cursor: pointer;
            }
            .ig-clean-card-thumb {
                position: relative;
                aspect-ratio: 1 / 1;
                cursor: pointer;
                background: #111;
            }
            .ig-clean-card-thumb img {
                width: 100%;
                height: 100%;
                object-fit: cover;
                display: block;
            }
            .ig-clean-card-badge {
                position: absolute;
                bottom: 6px;
                right: 6px;
                background: rgba(0, 0, 0, 0.75);
                color: #fff;
                font-size: 10px;
                padding: 2px 5px;
                border-radius: 4px;
            }
            .ig-clean-card-footer {
                display: flex;
                border-top: 1px solid #32353d;
            }
            .ig-clean-card-footer button {
                flex: 1;
                padding: 6px 4px;
                border: none;
                background: transparent;
                color: #ddd;
                font-size: 11px;
                cursor: pointer;
            }
            .ig-clean-card-footer button:hover {
                background: #2f323b;
                color: #fff;
            }
            .ig-clean-tag-list {
                padding: 12px 16px;
                max-height: 60vh;
                overflow-y: auto;
                display: flex;
                flex-direction: column;
                gap: 8px;
            }
            .ig-clean-tag-item {
                color: #4db5ff;
                text-decoration: none;
                font-size: 14px;
                padding: 6px 8px;
                border-radius: 6px;
                background: #22242a;
            }
            .ig-clean-tag-item:hover {
                background: #2d3038;
            }
            .ig-clean-empty {
                color: #999;
                font-size: 13px;
                padding: 8px 0;
            }
        `);

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') closeModals();
        });

        scanAndAttach();
        let timer = null;
        const obs = new MutationObserver(() => {
            clearTimeout(timer);
            timer = setTimeout(scanAndAttach, 200);
        });
        obs.observe(document.body, { childList: true, subtree: true });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initUI, { once: true });
    } else {
        initUI();
    }
})();

