		const sel = bar.querySelector('#sia-sort');
		if (sel) {
			sel.value = localStorage.getItem('sia-sort') || 'default';
			sel.addEventListener('change', () => {
				localStorage.setItem('sia-sort', sel.value);
				runLayout();
			});
