(function () {
  'use strict';

  const BOX_ID     = 'cee-vp-box';
  const BODY_ID    = 'cee-vp-body';
  const TITLE_ID   = 'cee-vp-title';
  const TITLE_TEXT = 'Twitter Viewer +';
