    } catch (e) {}
  }

  function findSection() {
    const aside = document.querySelector('aside[aria-label="Who to follow"]');
    if (aside) return aside;
    // Other named sidebar modules; single-post pages lead with "Relevant people".
    const wanted = ['you might like', 'who to follow', 'relevant people'];
    // New app: each sidebar module is a rounded <section> with an <h2>.
    for (const h of document.querySelectorAll('aside section h2')) {
      if (wanted.includes(h.textContent.trim().toLowerCase())) return h.closest('section');
    }
    const headings = document.querySelectorAll(
      'aside[role="complementary"] [role="heading"], [data-testid="sidebarColumn"] [role="heading"]');
    for (const h of headings) {
      if (wanted.includes(h.textContent.trim().toLowerCase())) return h.closest('aside') || h.parentElement;
    }
    return null;
  }

  function findHeadingTextEl(section) {
    const heading = section.querySelector('[role="heading"], h2');
    return heading ? (heading.querySelector('span') || heading) : null;
  }

  // The rounded sidebar card (first ancestor with a real border-radius).
  function findCard(aside) {
    let el = aside;
    for (let i = 0; i < 6 && el && el !== document.body; i++) {
      if ((parseFloat(getComputedStyle(el).borderTopLeftRadius) || 0) >= 12) return el;
      el = el.parentElement;
    }
    return aside.parentElement ? (aside.parentElement.parentElement || aside.parentElement) : aside;
  }

  function buildBox(referenceCard, headingTextEl) {
    const ref = getComputedStyle(referenceCard);
    MUTED = mutedColor();

    const box = document.createElement('div');
    box.id = BOX_ID;
    box.dataset.theme = themeKey();
    Object.assign(box.style, {
      backgroundColor: ref.backgroundColor,
      border: ref.borderTopWidth + ' solid ' + ref.borderTopColor,
      borderRadius: ref.borderTopLeftRadius,
      fontFamily: FONT_STACK,
      // currentColor for the focus rings; text and icons set their own colours
      color: headingTextEl ? getComputedStyle(headingTextEl).color : getComputedStyle(document.body).color,
      marginBottom: '16px', padding: '12px 16px', boxSizing: 'border-box',
    });

    box.appendChild(buildHeader(headingTextEl));

    const body = document.createElement('div');
    body.id = BODY_ID;
    if (collapsed) body.style.display = 'none';

    const tools = [
      { key: 'invert',        label: 'Show only checked' },
      { key: 'fastRetweet',   label: 'Fast retweet' },
      { key: 'hidePostVideo', label: 'Hide Post Video' },
      { key: 'nativePhotoMenu', label: 'Browser menu on photos' },
    ];

    body.appendChild(buildGroup('Filters', 'filters', headingTextEl, FILTERS, true));
    body.appendChild(buildSeparator(ref));
    body.appendChild(buildGroup('Display', 'display', headingTextEl, MODIFIERS, false));
    body.appendChild(buildSeparator(ref));
    body.appendChild(buildGroup('Tools', 'tools', headingTextEl, tools, false));

    box.appendChild(body);
    return box;
  }

  function buildSeparator(ref) {
    const sep = document.createElement('div');
    Object.assign(sep.style, { borderTop: '1px solid ' + ref.borderTopColor, margin: '12px 0' });
    return sep;
  }

  // A labelled, individually collapsible section of toggle rows.
  function buildGroup(title, key, headingTextEl, items, withCounter) {
    const wrap = document.createElement('div');

    const rows = document.createElement('div');
    Object.assign(rows.style, { display: 'flex', flexDirection: 'column', gap: '10px' });
    if (groupCollapsed[key]) rows.style.display = 'none';
    items.forEach(it => rows.appendChild(buildRow(it, headingTextEl, withCounter)));

    const head = document.createElement('div');
    head.setAttribute('role', 'button');
    head.setAttribute('aria-expanded', String(!groupCollapsed[key]));
    head.tabIndex = 0;
    Object.assign(head.style, {
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      cursor: 'pointer', marginBottom: groupCollapsed[key] ? '0' : '10px', userSelect: 'none',
    });

    const label = document.createElement('span');
    label.textContent = title;
    Object.assign(label.style, {
      fontFamily: FONT_STACK, fontSize: '13px', fontWeight: '700', color: MUTED,
    });

    const chev = document.createElement('span');
    Object.assign(chev.style, { flex: '0 0 auto', display: 'flex', alignItems: 'center', color: MUTED });
    chev.innerHTML = '<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" ' +
      'style="transition:transform .15s ease;fill:currentColor">' +
      '<path d="M3.543 8.96l1.414-1.42L12 14.59l7.043-7.05 1.414 1.42L12 17.41z"/></svg>';
    const svg = chev.firstChild;
    const applyChev = () => { svg.style.transform = groupCollapsed[key] ? 'rotate(-90deg)' : 'rotate(0deg)'; };
    applyChev();

    const toggle = (e) => {
      e.preventDefault();
      e.stopPropagation();
      groupCollapsed[key] = !groupCollapsed[key];
      rows.style.display = groupCollapsed[key] ? 'none' : 'flex';
      head.style.marginBottom = groupCollapsed[key] ? '0' : '10px';
      head.setAttribute('aria-expanded', String(!groupCollapsed[key]));
      applyChev();
      saveState();
    };
    head.addEventListener('click', toggle);
    head.addEventListener('keydown', (e) => { if (e.key === ' ' || e.key === 'Enter') toggle(e); });

    head.append(label, chev);
    wrap.append(head, rows);
    return wrap;
  }

  // Header: title + (reset, minimise) controls on the right.
  function buildHeader(headingTextEl) {
    const header = document.createElement('div');
    Object.assign(header.style, {
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      marginBottom: collapsed ? '0' : '12px',
    });

    const title = document.createElement('div');
    title.id = TITLE_ID;
    title.textContent = TITLE_TEXT;
    Object.assign(title.style, { cursor: 'default', userSelect: 'text', WebkitUserSelect: 'text', minWidth: '0' });
    if (headingTextEl) {
      const h = getComputedStyle(headingTextEl);
      Object.assign(title.style, {
        fontFamily: FONT_STACK, fontSize: h.fontSize, fontWeight: h.fontWeight,
        fontStyle: h.fontStyle, lineHeight: h.lineHeight, letterSpacing: h.letterSpacing, color: h.color,
      });
    }

    const controls = document.createElement('div');
    Object.assign(controls.style, { flex: '0 0 auto', display: 'flex', alignItems: 'center' });
    controls.append(buildReset(headingTextEl ? getComputedStyle(headingTextEl).color : getComputedStyle(document.body).color), buildMinimize(header));

    header.append(title, controls);
    return header;
  }

  function buildMinimize(header) {
    const btn = document.createElement('div');
    btn.setAttribute('role', 'button');
    btn.setAttribute('aria-label', 'Minimise panel');
    btn.setAttribute('aria-expanded', String(!collapsed));
    btn.tabIndex = 0;
    Object.assign(btn.style, {
      flex: '0 0 auto', marginLeft: '8px', padding: '2px', cursor: 'pointer',
      color: MUTED, display: 'flex', alignItems: 'center',
    });
    btn.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" ' +
      'style="transition:transform .15s ease;fill:currentColor">' +
      '<path d="M3.543 8.96l1.414-1.42L12 14.59l7.043-7.05 1.414 1.42L12 17.41z"/></svg>';
    const svg = btn.firstChild;
    const apply = () => { svg.style.transform = collapsed ? 'rotate(-90deg)' : 'rotate(0deg)'; };
    apply();

    const toggle = (e) => {
      e.preventDefault();
      e.stopPropagation();
      collapsed = !collapsed;
      apply();
      btn.setAttribute('aria-expanded', String(!collapsed));
      const body = document.getElementById(BODY_ID);
      if (body) body.style.display = collapsed ? 'none' : '';
      header.style.marginBottom = collapsed ? '0' : '12px';
      saveState();
    };
    btn.addEventListener('click', toggle);
    btn.addEventListener('keydown', (e) => { if (e.key === ' ' || e.key === 'Enter') toggle(e); });
    return btn;
  }

  // 18px row icon, or null if no glyph for the key.
  function buildIcon(key, color) {
    if (!ICONS[key]) return null;
    const span = document.createElement('span');
    Object.assign(span.style, { flex: '0 0 auto', display: 'inline-flex', alignItems: 'center' });
    span.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" ' +
      'style="fill:' + color + '"><path d="' + ICONS[key] + '"/></svg>';
    return span;
  }

  // One toggle row: icon + bold label (+ optional counter) on the left, checkbox on the right.
  function buildRow(item, headingTextEl, withCounter) {
    const themedColor = headingTextEl ? getComputedStyle(headingTextEl).color : '#e7e9ea';

    const row = document.createElement('label');
    Object.assign(row.style, {
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      width: '100%', cursor: 'pointer',
    });

    const left = document.createElement('span');
    Object.assign(left.style, { display: 'inline-flex', alignItems: 'center', gap: '8px', minWidth: '0' });

    const icon = buildIcon(item.key, themedColor);
    if (icon) left.append(icon);

    const text = document.createElement('span');
    text.textContent = item.label;
    Object.assign(text.style, {
      fontFamily: FONT_STACK, fontSize: '15px', fontWeight: '700', lineHeight: '20px',
      color: themedColor, userSelect: 'text', WebkitUserSelect: 'text',
    });
    left.append(text);

    if (withCounter) {
      const counter = document.createElement('span');
      counter.dataset.counter = item.key;
      counter.textContent = '(0/0)';
      Object.assign(counter.style, { fontSize: '13px', color: MUTED, whiteSpace: 'nowrap' });
      left.append(counter);
    }

    const box = buildCheckbox(item.key, item.label);
    row.append(left, box);
    // A <label> only forwards clicks to real form controls, and the box is a div.
    row.addEventListener('click', (e) => {
      if (box.contains(e.target) || String(window.getSelection())) return; // a drag that selected text is not a click
      box.click();
    });
    return row;
  }

  // "Reset all" as a refresh-icon button (sits left of the minimise chevron in the header).
  function buildReset(hoverColor) {
    const btn = document.createElement('div');
    btn.setAttribute('role', 'button');
    btn.setAttribute('aria-label', 'Reset all');
    btn.title = 'Reset all';
    btn.tabIndex = 0;
    Object.assign(btn.style, {
      flex: '0 0 auto', marginLeft: '8px', padding: '2px', cursor: 'pointer',
      color: MUTED, display: 'flex', alignItems: 'center',
    });
    btn.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" style="fill:currentColor">' +
      '<path d="M17.65 6.35C16.2 4.9 14.21 4 12 4c-4.42 0-7.99 3.58-7.99 8s3.57 8 7.99 8c3.73 0 6.84-2.55 7.73-6h-2.08c-.82 2.33-3.04 4-5.65 4-3.31 0-6-2.69-6-6s2.69-6 6-6c1.66 0 3.14.69 4.22 1.78L13 11h7V4l-2.35 2.35z"/></svg>';
    btn.addEventListener('mouseenter', () => { btn.style.color = hoverColor; });
    btn.addEventListener('mouseleave', () => { btn.style.color = MUTED; });

    const run = (e) => { e.preventDefault(); e.stopPropagation(); resetAll(); };
    btn.addEventListener('click', run);
    btn.addEventListener('keydown', (e) => { if (e.key === ' ' || e.key === 'Enter') run(e); });
    return btn;
  }

  function resetAll() {
    Object.keys(state).forEach(k => { state[k] = false; });
    FILTERS.forEach(f => hiddenIds[f.key].clear());
    hiddenRows.clear();
    saveState();
    const box = document.getElementById(BOX_ID);
    if (box) box.remove();
    ensureBox();
    applyFilters();
  }

  // Checkmark colour for an accent (black on light accents, else white).
  function contrastOn(color) {
    let r, g, b;
    const rgb = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    if (rgb) { r = +rgb[1]; g = +rgb[2]; b = +rgb[3]; }
    else {
      const h = color.replace('#', '').trim();
      if (h.length < 6) return '#fff';
      r = parseInt(h.slice(0, 2), 16); g = parseInt(h.slice(2, 4), 16); b = parseInt(h.slice(4, 6), 16);
    }
    return (0.299 * r + 0.587 * g + 0.114 * b) / 255 > 0.6 ? '#0f1419' : '#fff';
  }

  // The user's X accent: Control Panel for Twitter's CSS var, else the sidebar Post button's fill,
  // else an accent-coloured link (logged out).
  let lastAccent = '';
  let brandProbe = null;
  function accentColors() {
    let bg = '';
    try { bg = getComputedStyle(document.body).getPropertyValue('--cpft-theme').trim(); } catch (e) {}
    // New app: the accent is a CSS var (its Post button is plain white). Resolve it to a colour.
    if (!bg && getComputedStyle(document.documentElement).getPropertyValue('--color-brand').trim()) {
      // Kept outside <body>: adding it there would wake the body observer every frame.
      if (!brandProbe || !brandProbe.isConnected) {
        brandProbe = document.createElement('i');
        brandProbe.style.cssText = 'display:none;color:var(--color-brand)';
        document.documentElement.appendChild(brandProbe);
      }
      bg = getComputedStyle(brandProbe).color;
    }
    const post = !bg && document.querySelector('[data-testid="SideNav_NewTweet_Button"]');
    if (post) {
      // hover and press shade the fill, so keep the last clean read meanwhile
      bg = post.matches(':hover, :active') ? lastAccent : getComputedStyle(post).backgroundColor;
      if (bg === 'rgba(0, 0, 0, 0)') bg = '';
    }
    if (!bg) {
      const link = document.querySelector('[data-testid="tweetText"] a[href], a[href*="/hashtag/"]');
      if (link) bg = getComputedStyle(link).color || '';
    }
    if (!bg) bg = '#1d9bf0';
    lastAccent = bg;
    return { bg, fg: contrastOn(bg) };
  }

  // Theme colours are copied into the panel at build time, so a change to either means a rebuild.
  function themeKey() {
    return getComputedStyle(document.body).backgroundColor + '|' + accentColors().bg;
  }

  // X-style square checkbox; checked fill uses the live accent colour.
  function buildCheckbox(key, label) {
    const box = document.createElement('div');
    box.setAttribute('role', 'checkbox');
    box.setAttribute('aria-label', label);
    box.tabIndex = 0;
    Object.assign(box.style, {
      flex: '0 0 auto', width: '20px', height: '20px', marginLeft: '12px',
      borderRadius: '4px', boxSizing: 'border-box',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      cursor: 'pointer', transition: 'background-color .15s ease, border-color .15s ease',
    });

    const render = () => {
      const accent = accentColors();
      box.setAttribute('aria-checked', String(state[key]));
      box.style.border = '2px solid ' + (state[key] ? accent.bg : MUTED);
      box.style.backgroundColor = state[key] ? accent.bg : 'transparent';
      box.innerHTML = state[key]
        ? '<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">' +
          '<path fill="' + accent.fg + '" d="M9 16.2 4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4z"/></svg>'
        : '';
    };
    render();

    const toggle = (e) => {
      e.preventDefault();
      e.stopPropagation();
      state[key] = !state[key];
      if (!state[key] && hiddenIds[key]) hiddenIds[key].clear(); // filters only; modifiers have none
      hiddenRows.clear(); // rows out of view keep their rule otherwise; the pass re-adds what still hides
      render();
      applyFilters();
      saveState();
    };
    box.addEventListener('click', toggle);
    box.addEventListener('keydown', (e) => { if (e.key === ' ' || e.key === 'Enter') toggle(e); });
    return box;
  }

  // Profile handle from the URL, or null when not on a profile feed.
  function getProfileOwner() {
    const seg = location.pathname.split('/').filter(Boolean);
    if (!seg.length) return null;
    const reserved = new Set(['home', 'explore', 'notifications', 'messages', 'settings', 'i', 'search',
      'compose', 'hashtag', 'bookmarks', 'lists', 'jobs', 'communities', 'tos', 'privacy', 'about']);
    if (reserved.has(seg[0].toLowerCase())) return null;
    if (seg.includes('status')) return null; // single-tweet page, not a feed
    return seg[0];
  }

  // Author handle + status id from a tweet's permalink (handles relative and absolute hrefs).
  function permalinkInfo(article) {
    const wrapHref = article.parentElement && article.parentElement.getAttribute('data-href'); // new app
    const link = article.querySelector('a[href*="/status/"]');
    const href = wrapHref || (link && link.getAttribute('href'));
    if (!href) return { author: null, id: null };
    const m = href.match(/(?:https?:\/\/[^/]+)?\/([^/]+)\/status\/(\d+)/);
    return m ? { author: m[1].toLowerCase(), id: m[2] } : { author: null, id: null };
  }

  // Classify a cell (may be a multi-tweet conversation) -> { id, cats } or null.
  function classify(cell) {
    const articles = Array.from(cell.querySelectorAll(TWEET_SEL));
    if (!articles.length) return null;

    const owner = (activeProfile || '').toLowerCase();
    const infos = articles.map(a => {
      const { author, id } = permalinkInfo(a);
      const s = socialContext(a).toLowerCase();

      // The quoted-tweet wrapper, so its nested text/avatars don't leak into this tweet's signals.
      const quoteEl = a.querySelector(QUOTE_SEL) || a.querySelector('div[role="link"]');
      const hasQuote = !!(quoteEl && quoteEl.querySelector(NAME_SEL));

      // Thread connector beside the avatar (new app): a line above = the reply, one below = its parent.
      const av = a.querySelector('[data-post-avatar]');
      const upNew = !!(av && av.previousElementSibling);
      const downNew = !!(av && av.nextElementSibling);

      // "Replying to" that belongs to this tweet, not to a reply shown inside the quoted tweet.
      let replyingTo = false;
      for (const d of a.querySelectorAll('div[dir="ltr"], div.text-secondary')) {
        if (hasQuote && quoteEl.contains(d)) continue;
        if (/^\s*replying to/i.test(d.textContent)) { replyingTo = true; break; }
      }

      return {
        author, id, replyingTo,
        pinned: /pinned/.test(s),
        retweet: /repost|retweet/.test(s),
        quote: hasQuote,
        // Thread-connector line: anyLine = in a thread; upLine = the reply itself.
        anyLine: upNew || downNew || !!a.querySelector('.r-1bnu78o.r-f8sm7e.r-m5arl1'),
        upLine:  upNew || !!a.querySelector('.r-1bnu78o.r-f8sm7e.r-m5arl1.r-1p0dtai'),
      };
    });

    const last        = infos[infos.length - 1];
    const multi       = articles.length >= 2;
    const otherAuthor = !!owner && infos.some(x => x.author && x.author !== owner);

    // "Reposted" context always means a retweet, even of a reply or quote: the owner's action is
    // the repost, so it outranks reply/quote/thread.
    const isRetweet = infos.some(x => x.retweet);

    // Reply: thread line, "Replying to", or in-cell convo with another author. Reposts are excluded
    // (a repost is the owner's repost, not their reply).
    const isReply = !isRetweet && (infos.some(x => x.upLine || x.replyingTo) || (multi && otherAuthor));
    // A reply's parent context: hidden with replies but not counted.
    const isThreadPart = !isRetweet && (infos.some(x => x.anyLine) || isReply);
    const replyContext = isThreadPart && !isReply;

    const isPinned = infos.some(x => x.pinned);
    const isQuote  = !isRetweet && !isThreadPart && last.quote;
    const isPost   = !isPinned && !isRetweet && !isQuote && !isThreadPart;

    // Independent of type: has media?
    const hasMedia = !!cell.querySelector(MEDIA_SEL);

    let id = null;
    for (let i = infos.length - 1; i >= 0; i--) { if (infos[i].id) { id = infos[i].id; break; } }

    return {
      id, replyContext,
      cats: {
        pinned: isPinned, replies: isReply, quotes: isQuote, retweets: isRetweet, posts: isPost,
        mediaposts: hasMedia, textonly: !hasMedia,
      },
    };
  }

  // "Pinned" / "<name> reposted" line above a tweet. The new app has no test id for it: it is the
  // article's leading row(s) before the avatar row.
  function socialContext(article) {
    const old = article.querySelector('[data-testid="socialContext"]');
    if (old) return old.textContent;
    const av = article.querySelector('[data-post-avatar]');
    if (!av) return '';
    let s = '';
    for (const child of article.children) {
      if (child.contains(av)) break;
      s += child.textContent + ' ';
    }
    return s;
  }

  // The new app's timeline is a virtual list of absolutely placed rows that ignores 0-height rows, so
  // display:none leaves a gap where the post was. A 1px row is the smallest size it re-flows around.
  // It also measures each row the moment React mounts it and shifts the scroll when a row above the
  // viewport changes size, so a row hidden only after mounting makes the page jump. Rows are therefore
  // hidden by a stylesheet rule keyed on the post link, which already applies when a row remounts.
  const hiddenRows = new Set(); // data-href of each hidden row's first post
  const rowStyle = document.createElement('style');
  let rowCss = '';
  function rowKey(cell) {
    const post = cell.querySelector(':scope > [data-href], :scope > * > [data-href]');
    return post ? post.getAttribute('data-href') : null;
  }
  function writeRowCss() {
    const sels = Array.from(hiddenRows, k => {
      const pin = k.match(/^#(\d+) (.*)$/); // pinned row: "#<data-index> <href>"
      const q = '[data-href="' + CSS.escape(pin ? pin[2] : k) + '"]';
      return 'main li[data-index' + (pin ? '="' + pin[1] + '"' : '') + ']:has(> ' + q + ', > * > ' + q + ')';
    });
    const css = sels.length
      ? sels.join(',\n') + '{height:1px!important;overflow:hidden!important;visibility:hidden!important;overflow-anchor:none}'
      : '';
    if (css !== rowCss) rowStyle.textContent = rowCss = css;
  }

  // A pinned post often shows again further down the feed with the same link. Its rule is pinned to its
  // row index too, so hiding one copy never hides or unhides the other.
  function setCellHidden(cell, hide, pinned) {
    let key = cell.tagName === 'LI' && rowKey(cell);
    if (key) {
      if (pinned) key = '#' + cell.getAttribute('data-index') + ' ' + key;
      if (hide) addCapped(hiddenRows, key, ROW_CAP); else hiddenRows.delete(key);
      return;
    }
    if (cell.tagName === 'LI') {
      cell.style.height = hide ? '1px' : '';
      cell.style.overflow = hide ? 'hidden' : '';
      cell.style.visibility = hide ? 'hidden' : '';
      cell.style.overflowAnchor = hide ? 'none' : '';
    } else {
      cell.style.display = hide ? 'none' : '';
    }
  }

  // A reply-expander cell (conversation link, no tweet).
  function isReplyExpander(cell) {
    if (cell.querySelector(TWEET_SEL)) return false;
    if (cell.querySelector('a[href*="/i/status/"]')) return true;
    // Bare "Show replies" too: a reply with its own replies gets one under it, with no /i/status/ link.
    return /show\s+(?:(?:more|additional|this)\b[^]*?)?(?:repl|thread)/i.test(cell.textContent || '');
  }

  // X fixes the media height on several wrappers (multi-photo posts are a swipe carousel), so clip or hide
  // the topmost wrapper that is still just the media. Found once while unstyled, then cached: once a
  // carousel's first photo is clipped its ancestors shrink and a fresh walk would climb into the post.
  const blockOf = new WeakMap();
  const isBlock = new WeakSet();
  function mediaBlock(el, tweet) {
    const cached = blockOf.get(el);
    if (cached && cached.contains(el)) return cached;
    const h = el.getBoundingClientRect().height;
    if (!h) return null; // hidden or not laid out: styling now would cache a clipped size; a later pass gets it
    let top = el;
    while (!isBlock.has(top)) {
      const p = top.parentElement;
      if (!p || p === tweet || p.getBoundingClientRect().height > h + 12 ||
          p.querySelector(TEXT_SEL + ', ' + NAME_SEL)) break;
      top = p;
    }
    blockOf.set(el, top);
    isBlock.add(top);
    return top;
  }

  function applyTweetMods() {
    const modsActive = state.compact || state.hideText || state.hideMedia || state.hideEngagement;
    if (!modsActive && !modsWereActive) return; // nothing to apply, nothing left to restore

    document.querySelectorAll(TWEET_SEL).forEach(tweet => {
      tweet.querySelectorAll(TEXT_SEL).forEach(el => {
        el.style.display = state.hideText ? 'none' : '';
      });
      // "Show more" expander sits beside tweetText, so hide/restore it too.
      if (state.hideText || textWasActive) {
        tweet.querySelectorAll('span').forEach(sp => {
          if (sp.textContent.trim() !== 'Show more') return;
          let node = sp;
          while (node.parentElement && node.parentElement !== tweet &&
                 node.parentElement.textContent.trim() === 'Show more') node = node.parentElement;
          node.style.display = state.hideText ? 'none' : '';
        });
      }

      // Media (photos, videos, link-card embeds). Outermost block only: a video's videoComponent sits inside its tweetPhoto.
      tweet.querySelectorAll(MEDIA_SEL).forEach(el => {
        if (el.parentElement.closest(MEDIA_SEL)) return;
        const target = mediaBlock(el, tweet);
        if (!target) return;
        // X's video player shrinks to a clipped box and keeps that size after unclipping, so pin its height.
        if (state.compact && !state.hideMedia && (el.matches(VIDEO_SEL) || el.querySelector(VIDEO_SEL))) {
          const h = el.getBoundingClientRect().height;
          if (!el.style.height && h) el.style.height = h + 'px';
        } else {
          el.style.height = '';
        }
        if (state.hideMedia) {
          target.style.display = 'none';
          target.style.maxHeight = ''; target.style.overflow = '';
        } else if (state.compact) {
          target.style.display = '';
          target.style.maxHeight = COMPACT_MEDIA_MAX; target.style.overflow = 'hidden';
        } else {
          target.style.display = '';
          target.style.maxHeight = ''; target.style.overflow = '';
        }
      });
      // Engagement bar (the reply / repost / like / views action row).
      tweet.querySelectorAll(REPLY_BTN).forEach(btn => {
        const bar = btn.closest('[role="group"]');
        if (bar) bar.style.display = state.hideEngagement ? 'none' : '';
      });
    });
    textWasActive = state.hideText;
    modsWereActive = modsActive;
  }

  function applyFilters() {
    // Reset cumulative counts when switching to a different profile.
    const owner = getProfileOwner();
    if (owner !== activeProfile) {
      activeProfile = owner;
      FILTERS.forEach(f => { seen[f.key].clear(); hiddenIds[f.key].clear(); });
      hiddenRows.clear();
    }

    // Cheap and rare: strip "Post Video" from the video right-click menu.
    document.querySelectorAll('[data-testid="postVideoContextMenuItem"]').forEach(el => {
      el.style.display = state.hidePostVideo ? 'none' : '';
    });
    document.querySelectorAll('[role="menuitem"]').forEach(el => { // new app: no test id, match the label
      if (/^post video$/i.test(el.textContent.trim())) el.style.display = state.hidePostVideo ? 'none' : '';
    });

    // On a profile's Replies tab nearly every post is a reply: hiding them empties the page and X then
    // loads more forever. "Show only checked" (only replies there) is still fine.
    const skipReplies = !state.invert && /\/with_replies\/?$/.test(location.pathname);
    const on = k => state[k] && !(k === 'replies' && skipReplies);

    const box = document.getElementById(BOX_ID);
    const anyFilterOn = FILTERS.some(f => on(f.key)); // not tied to the panel: X drops the sidebar below 1024px
    filtering = anyFilterOn;
    loadAhead();

    // Only scan/classify cells while filtering is engaged, plus one pass to restore when it stops.
    if (anyFilterOn || filtersWereActive) {
      document.querySelectorAll(CELL_SEL).forEach(cell => {
        const info = classify(cell);
        if (!info) {
          // Non-tweet cell: "Show more replies" expanders track the replies filter.
          let hideCell = false;
          if (isReplyExpander(cell)) {
            hideCell = state.invert ? (anyFilterOn && !on('replies')) : on('replies');
          }
          setCellHidden(cell, hideCell);
          return;
        }

        let matched = false;
        FILTERS.forEach(f => {
          if (!info.cats[f.key]) {
            // A link card can load after the first pass and move a post from text-only to media. Only these two:
            // the pinned post also shows unpinned further down, and that copy must not uncount it.
            if (info.id && (f.key === 'mediaposts' || f.key === 'textonly')) {
              seen[f.key].delete(info.id); hiddenIds[f.key].delete(info.id);
            }
            return;
          }
          if (info.id) addCapped(seen[f.key], info.id);
          if (on(f.key)) { matched = true; if (info.id) addCapped(hiddenIds[f.key], info.id); }
        });
        // A reply's parent context counts with the replies filter.
        if (info.replyContext && on('replies')) matched = true;

        const hide = state.invert ? (anyFilterOn && !matched) : matched;
        setCellHidden(cell, hide, info.cats.pinned);
      });
      writeRowCss();

      if (box) {
        FILTERS.forEach(f => {
          const el = box.querySelector('[data-counter="' + f.key + '"]');
          if (!el) return;
          // Only on change: every write is a childList mutation, and the body observer
          // would re-run this pass on the next frame, forever.
          const text = '(' + (state[f.key] ? hiddenIds[f.key].size : 0) + '/' + seen[f.key].size + ')';
          if (el.textContent !== text) el.textContent = text;
        });
      }
      filtersWereActive = anyFilterOn;
    }

    applyTweetMods();
  }

  function ensureBox() {
    const old = document.getElementById(BOX_ID);
    if (old) {
      if (old.dataset.theme === themeKey()) return;
      old.remove();
    }
    const section = findSection();
    if (!section) return;
    const card = findCard(section);
    if (!card || !card.parentNode) return;
    card.parentNode.insertBefore(buildBox(card, findHeadingTextEl(section)), card);
  }

  // Fast retweet: after the repost button is clicked, auto-confirm the repost when X's menu opens,
  // skipping the Repost/Quote chooser. Observes only for a short window after each click.
  function setupFastRetweet() {
    let timer = null;
    const obs = new MutationObserver(() => {
      const confirm = document.querySelector('[data-testid="retweetConfirm"], [data-testid="unretweetConfirm"]') ||
        // new app: plain menu items, matched by label
        Array.from(document.querySelectorAll('[role="menu"] [role="menuitem"]'))
          .find(el => /^(repost|undo repost)$/i.test(el.textContent.trim()));
      if (confirm) { stop(); confirm.click(); }
    });
    function stop() { obs.disconnect(); if (timer) { clearTimeout(timer); timer = null; } }
    document.addEventListener('click', (e) => {
      if (!state.fastRetweet) return;
      const t = e.target;
      if (!t || !t.closest ||
          !t.closest('[data-testid="retweet"], [data-testid="unretweet"], [data-engagement-action="retweet"]')) return;
      obs.observe(document.body, { childList: true, subtree: true });
      if (timer) clearTimeout(timer);
      timer = setTimeout(stop, 1500); // give up if the menu never appears
    }, true);
  }

  // X cancels the browser's menu on feed photos and draws its own (Copy photo link, Post Photo). A capture
  // listener on window runs before X's handlers on its React root, so stopping the event there lets the
  // browser's menu open on the photo's own <img>.
  window.addEventListener('contextmenu', (e) => {
    if (!state.nativePhotoMenu) return;
    const t = e.target;
    if (!t || !t.closest || !t.closest('[data-testid="tweetPhoto"] img, a[data-engagement-action="media"] img')) return;
    // Videos and GIFs sit inside tweetPhoto too, with an <img> poster; they keep X's menu.
    if (t.closest('[data-testid="videoComponent"], [data-testid="videoPlayer"]')) return;
    const trigger = t.closest('[data-slot="xds-context-menu-trigger"]');
    if (trigger && trigger.querySelector('video')) return;
    e.stopImmediatePropagation();
  }, true);

  // New app: X asks for the next page once, 1.75 screens before the end. With most rows hidden that is
  // too late and scrolling stalls at the bottom while the page loads, so ask from 4 screens out.
  // X ignores the call while that page is already loading.
  let filtering = false;
  let lastLoadAhead = 0;
  function loadAhead() {
    if (!filtering || Date.now() - lastLoadAhead < 500) return;
    if (document.documentElement.scrollHeight - scrollY - innerHeight > innerHeight * 4) return;
    const row = document.querySelector('main li[data-index]');
    if (!row) return; // old app
    const raw = row.wrappedJSObject || row; // Firefox sandbox hides the page's React keys
    const key = Object.keys(raw).find(k => k.startsWith('__reactFiber$'));
    for (let f = key && raw[key], i = 0; f && i < 60; f = f.return, i++) {
      const p = f.memoizedProps;
      if (p && typeof p.onNearEnd === 'function') {
        lastLoadAhead = Date.now();
        p.onNearEnd();
        return;
      }
    }
  }
  window.addEventListener('scroll', loadAhead, { passive: true });

  let scheduled = false;
  function schedule() {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(() => { scheduled = false; ensureBox(); applyFilters(); });
  }

  // The panel's controls are divs, so they get an explicit keyboard focus ring.
  const focusStyle = document.createElement('style');
  focusStyle.textContent = '#' + BOX_ID + ' [role="button"]:focus-visible,#' + BOX_ID + ' [role="checkbox"]:focus-visible' +
    '{outline:2px solid currentColor;outline-offset:2px;border-radius:4px}';
  document.head.appendChild(focusStyle);
  document.head.appendChild(rowStyle);

  loadState();
  setupFastRetweet();
  new MutationObserver(schedule).observe(document.body, { childList: true, subtree: true });
  schedule();
})();

