const REGEX_CHANNEL = /.*\/(user|channel|c)\/.+\/videos/u;
const REGEX_USER = /.*\/@.*/u;
const REGEX_PLAYLIST_LISTING_PATH =
	/^\/feed\/(?:library|you)\/?$|\/(?:playlists|podcasts|courses|releases)\/?$/u;

