	// ===========================================================

	const updateClassOnMembersItems = async () => {
		try {
			const section = determineYoutubeSection();

			document.querySelectorAll('.YT-HWV-MEMBERS-DIMMED').forEach((el) => {
				el.classList.remove('YT-HWV-MEMBERS-DIMMED');
			});
			document.querySelectorAll('.YT-HWV-MEMBERS-HIDDEN').forEach((el) => {
				el.classList.remove('YT-HWV-MEMBERS-HIDDEN');
			});

			const state = await stateGet(`YTHWV_STATE_MEMBERS_${section}`);

			const membersContainers = findMembersContainers();

			membersContainers.forEach((item) => {
				// Add current class
				if (state === 'dimmed') {
					item.classList.add('YT-HWV-MEMBERS-DIMMED');
				} else if (state === 'hidden') {
					item.classList.add('YT-HWV-MEMBERS-HIDDEN');
				}
			});
		} catch (error) {
			console.error('[YT-HWV]', error);
		}
	};

	// ===========================================================
	// Subscribed-channel hiding (homepage only).
	//
	// Unlike watched/shorts/mixes, "subscribed" is not marked on a feed
	// card, so we build the viewer's own subscription list once (from
	// /feed/channels), cache it per-account, then match it against the
	// channel link on each homepage tile.

	// In-memory set of normalized identifiers (lowercased @handles + UC ids)
	let subbedSet = null;

	const applySubbedTintSetting = () => {
		let pct = 45;
		try {
			pct = Number(gmc.get('SUBBED_DIM_BRIGHTNESS'));
		} catch (_) {
			/* defaults */
		}
		if (!Number.isFinite(pct)) pct = 45;
		pct = Math.max(0, Math.min(100, pct));
		document.documentElement.style.setProperty(
			'--ythwv-subbed-brightness',
			String(pct / 100),
		);
	};

	// A per-account key so each signed-in user gets their own cached list
	const getUserId = () => {
		const html = document.documentElement.innerHTML;
		const m =
			html.match(REGEX_DATASYNC_ID) || html.match(REGEX_DELEGATED_SESSION_ID);
		return m ? m[1] : 'default';
	};

	// Which signed-in account (authuser index) this tab uses, so
	// subscription fetches hit the right account instead of account 0.
	const getSessionIndex = () => {
		const m = document.documentElement.innerHTML.match(REGEX_SESSION_INDEX);
		return m ? m[1] : '0';
	};

	// Handles can arrive \u-escaped (ytInitialData embeds non-ASCII that
	// way); decode to raw unicode so they compare equal to decoded DOM hrefs.
	const decodeHandle = (raw) => {
		let handle = raw;
		if (raw.includes('\\u')) {
			try {
				handle = JSON.parse(`"${raw}"`);
			} catch (_) {
				/* keep raw */
			}
		}
		return handle.toLowerCase();
	};

	const parseSubsFromHtml = (html) => {
		const ids = new Set();
		const handles = new Set();
		for (const m of html.matchAll(
			/"(?:channelId|browseId)":"(UC[0-9A-Za-z_-]{22})"/g,
		)) {
			ids.add(m[1]);
		}
		for (const m of html.matchAll(
			/"(?:canonicalBaseUrl|url)":"\\?\/(@(?:\\u[0-9a-fA-F]{4}|[^"\\/])+)"/g,
		)) {
			handles.add(decodeHandle(m[1]));
		}
		return { handles: [...handles], ids: [...ids] };
	};

	// Max number of continuation pages to walk when collecting subscriptions
	const SUBS_FETCH_MAX_PAGES = 60;

	const matchFirst = (text, re) => {
		const m = text.match(re);
		return m ? m[1] : null;
	};

	const getContinuationToken = (text) => {
		const m = text.match(REGEX_CONTINUATION_TOKEN);
		return m ? m[1] : null;
	};

	// Compute the SAPISIDHASH auth header YouTube's web client uses, so the
	// continuation requests return the viewer's real subscriptions instead
	// of a logged-out response.
	const sapisidHash = async () => {
		try {
			const sapisid = (document.cookie.match(REGEX_SAPISID) ||
				document.cookie.match(REGEX_SECURE_3PAPISID))?.[1];
			if (!sapisid) return null;
			const origin = 'https://www.youtube.com';
			const ts = Math.floor(Date.now() / 1000);
			const enc = new TextEncoder().encode(`${ts} ${sapisid} ${origin}`);
			const buf = await crypto.subtle.digest('SHA-1', enc);
			const hex = [...new Uint8Array(buf)]
				.map((b) => b.toString(16).padStart(2, '0'))
				.join('');
			return `SAPISIDHASH ${ts}_${hex}`;
		} catch (_) {
			return null;
		}
	};

	const fetchSubs = async (force = false) => {
		const key = `YTHWV_SUBS_${getUserId()}`;
		let ttlHours = 24;
		try {
			ttlHours = Number(gmc.get('SUBBED_REFRESH_HOURS')) || 24;
		} catch (_) {
			/* defaults */
		}

		let cached = null;
		try {
			const raw = await stateGet(key, null);
			if (raw) cached = JSON.parse(raw);
		} catch (_) {
			/* ignore */
		}

		const isFresh =
			cached &&
			Date.now() - cached.updated < ttlHours * 3600 * 1000 &&
			(cached.ids.length || cached.handles.length);

		if (!force && isFresh) {
			subbedSet = new Set([...cached.ids, ...cached.handles]);
			return subbedSet;
		}

		try {
			const ids = new Set();
			const handles = new Set();

			// /feed/channels lazy-loads, so the initial HTML holds only the
			// first batch of subscriptions. Parse that, then follow the list's
			// continuation tokens through the InnerTube API to collect every
			// subscription. Otherwise channels past the first page never make
			// it into the set and can't be hidden.
			const authUser = getSessionIndex();
			const res = await fetch(
				`https://www.youtube.com/feed/channels?authuser=${authUser}`,
				{ credentials: 'include' },
			);
			const html = await res.text();
			let parsed = parseSubsFromHtml(html);
			for (const x of parsed.ids) ids.add(x);
			for (const x of parsed.handles) handles.add(x);

			const apiKey = matchFirst(html, REGEX_INNERTUBE_API_KEY);
			const clientVersion =
				matchFirst(html, REGEX_INNERTUBE_CLIENT_VERSION) ||
				matchFirst(html, REGEX_CLIENT_VERSION);
			const auth = await sapisidHash();
			let token = getContinuationToken(html);
			const seen = new Set();
			let pages = 0;

			while (
				token &&
				apiKey &&
				auth &&
				!seen.has(token) &&
				pages < SUBS_FETCH_MAX_PAGES
			) {
				seen.add(token);
				pages += 1;
				let json;
				try {
					const cres = await fetch(
						`https://www.youtube.com/youtubei/v1/browse?key=${apiKey}&prettyPrint=false`,
						{
							body: JSON.stringify({
								context: {
									client: {
										clientName: 'WEB',
										clientVersion: clientVersion || '2.20240101.00.00',
										gl: 'US',
										hl: 'en',
									},
								},
								continuation: token,
							}),
							credentials: 'include',
							headers: {
								Authorization: auth,
								'Content-Type': 'application/json',
								'X-Goog-AuthUser': authUser,
								'X-Origin': 'https://www.youtube.com',
							},
							method: 'POST',
						},
					);
					if (!cres.ok) break;
					json = await cres.text();
				} catch (_) {
					break;
				}
				const before = ids.size + handles.size;
				parsed = parseSubsFromHtml(json);
				for (const x of parsed.ids) ids.add(x);
				for (const x of parsed.handles) handles.add(x);
				token = getContinuationToken(json);
				if (ids.size + handles.size === before && !token) break;
			}

			if (ids.size || handles.size) {
				const out = {
					handles: [...handles],
					ids: [...ids],
					updated: Date.now(),
				};
				await stateSet(key, JSON.stringify(out));
				subbedSet = new Set([...out.ids, ...out.handles]);
				logDebug(
					`Loaded ${out.ids.length} ids / ${out.handles.length} handles`,
				);
				return subbedSet;
			}
		} catch (error) {
			console.error('[YT-HWV] Failed to fetch subscriptions', error);
		}

		// Fall back to whatever we had cached
		if (cached) subbedSet = new Set([...cached.ids, ...cached.handles]);
		return subbedSet;
	};

	// Coalesce concurrent callers into one fetch walk: on a cold cache,
	// every debounced run() would otherwise start its own 60-page
	// continuation crawl while the set is still loading.
	let subsLoadInFlight = null;
	const loadSubs = (force = false) => {
		if (!subsLoadInFlight) {
			subsLoadInFlight = fetchSubs(force).finally(() => {
				subsLoadInFlight = null;
			});
		}
		return subsLoadInFlight;
	};

	// Reduce a channel link to a comparable id (@handle or UC id), or null
	const normalizeChannelHref = (href) => {
		if (!href) return null;
		let path = href;
		try {
			path = new URL(href, location.origin).pathname;
		} catch (_) {
			/* href was already a path */
		}
		path = path.replace(REGEX_LEADING_SLASH, '');
		if (path.startsWith('@')) {
			// Hrefs percent-encode non-ASCII handles; the subscription set
			// stores them decoded, so decode before comparing.
			const handle = path.split('/')[0];
			try {
				return decodeURIComponent(handle).toLowerCase();
			} catch (_) {
				return handle.toLowerCase();
			}
		}
		const m = path.match(REGEX_CHANNEL_ID_PATH);
		return m ? m[1] : null;
	};

	const findSubscribedContainers = () => {
		if (!subbedSet || subbedSet.size === 0) return [];

		const containers = [];
		document.querySelectorAll('ytd-rich-item-renderer').forEach((tile) => {
			// Scan the tile's links for the uploader's channel link.
			// Video/short/mix links normalize to null, so only a real
			// channel link can match the subscription set.
			for (const a of tile.querySelectorAll('a[href]')) {
				const id = normalizeChannelHref(a.getAttribute('href'));
				if (id && subbedSet.has(id)) {
					containers.push(tile);
					break;
				}
			}
		});
		return containers;
	};

	const updateClassOnSubscribedItems = async () => {
		try {
			document.querySelectorAll('.YT-HWV-SUBBED-DIMMED').forEach((el) => {
				el.classList.remove('YT-HWV-SUBBED-DIMMED');
			});
			document.querySelectorAll('.YT-HWV-SUBBED-HIDDEN').forEach((el) => {
				el.classList.remove('YT-HWV-SUBBED-HIDDEN');
			});

			// Homepage only: elsewhere this would nuke whole pages.
			if (location.pathname !== '/') return;

			const state = await stateGet('YTHWV_STATE_SUBBED', 'normal');
			if (state === 'normal') return;

			if (!subbedSet) await loadSubs(false);
			if (!subbedSet || subbedSet.size === 0) return;

			findSubscribedContainers().forEach((item) => {
				if (state === 'dimmed') {
					item.classList.add('YT-HWV-SUBBED-DIMMED');
				} else if (state === 'hidden') {
					item.classList.add('YT-HWV-SUBBED-HIDDEN');
				}
			});
		} catch (error) {
			console.error('[YT-HWV]', error);
		}
	};

	// ===========================================================

	const updateClassOnPlayablesShelves = () => {
		try {
			document.querySelectorAll('.YT-HWV-PLAYABLES-HIDDEN').forEach((el) => {
				el.classList.remove('YT-HWV-PLAYABLES-HIDDEN');
			});

			if (!gmc.get('HIDE_PLAYABLES')) return;

			document
				.querySelectorAll(
					'ytd-mini-game-card-view-model, a[href^="/playables"]',
				)
				.forEach((el) => {
					el.closest('ytd-rich-section-renderer')?.classList.add(
						'YT-HWV-PLAYABLES-HIDDEN',
					);
				});
		} catch (error) {
			console.error('[YT-HWV]', error);
		}
	};

	// ===========================================================
	// The home grid is one flex-wrap list, and each full-width section in
	// it (Playables, "Explore more topics", news...) forces a line break,
	// so hiding videos ahead of a section leaves a short row above it.
	// Push such sections down with CSS `order` until the row before them
	// is full. Orders are negative so tiles YouTube appends later (order 0)
	// still land after everything already placed.

	const isShown = (el) =>
		el.checkVisibility ? el.checkVisibility() : el.offsetParent !== null;

	const reflowRichGrids = () => {
		try {
			for (const contents of document.querySelectorAll(
				'ytd-rich-grid-renderer > #contents',
			)) {
				const perRow =
					Number.parseInt(
						getComputedStyle(contents.parentElement).getPropertyValue(
							'--ytd-rich-grid-items-per-row',
						),
						10,
					) || 1;
				const placed = [];
				let pending = [];
				let column = 0;
				let deferred = false;

				for (const el of contents.children) {
					if (el.tagName === 'YTD-CONTINUATION-ITEM-RENDERER') continue;
					if (!isShown(el)) {
						placed.push(el);
					} else if (el.tagName === 'YTD-RICH-ITEM-RENDERER') {
						placed.push(el);
						column = (column + 1) % perRow;
						if (column === 0) {
							placed.push(...pending);
							pending = [];
						}
					} else if (column === 0) {
						placed.push(el);
					} else {
						pending.push(el);
						deferred = true;
					}
				}
				placed.push(...pending);

				placed.forEach((el, i) => {
					if (deferred) {
						el.style.order = String(i - placed.length);
					} else {
						el.style.removeProperty('order');
					}
				});
			}
		} catch (error) {
			console.error('[YT-HWV]', error);
		}
	};

	// ===========================================================

	const renderButtons = async () => {
		// Find button area target
		const target = findButtonAreaTarget();
		if (!target) return;

		// Generate buttons area DOM
		const buttonArea = document.createElement('div');
		buttonArea.classList.add('YT-HWV-BUTTONS');

		// Render buttons
		for (const { icon, iconHidden, name, stateKey, type, global } of BUTTONS) {
			// For toggle buttons, determine where in GM storage they track state.
			// Most toggles track per-section; "global" toggles share one state.
			const section = determineYoutubeSection();
			let storageKey = null;
			if (stateKey) {
				storageKey = global ? stateKey : [stateKey, section].join('_');
			}
			const toggleButtonState = storageKey
				? await stateGet(storageKey, 'normal')
				: 'normal';

			// Generate button DOM
			const button = document.createElement('button');
			if (type === 'toggle') {
				button.title = global
					? `${name} : currently "${toggleButtonState}"`
					: `${name} : currently "${toggleButtonState}" for section "${section}"`;
			} else {
				button.title = `${name}`;
			}
			button.classList.add('YT-HWV-BUTTON');
			if (toggleButtonState !== 'normal')
				button.classList.add('YT-HWV-BUTTON-DISABLED');
			button.innerHTML = toggleButtonState === 'hidden' ? iconHidden : icon;
			buttonArea.appendChild(button);

			// Attach events for toggle buttons
			switch (type) {
				case 'toggle':
					button.addEventListener('click', async () => {
						logDebug(`Button ${name} clicked. State: ${toggleButtonState}`);

						let newState = 'dimmed';
						if (toggleButtonState === 'dimmed') {
							newState = 'hidden';
						} else if (toggleButtonState === 'hidden') {
							newState = 'normal';
						}

						await stateSet(storageKey, newState);

						await updateClassOnWatchedItems();
						await updateClassOnShortsItems();
						await updateClassOnMixesItems();
						await updateClassOnMembersItems();
						await updateClassOnSubscribedItems();
						updateClassOnPlayablesShelves();
						reflowRichGrids();
						await renderButtons();
					});
					break;
				case 'settings':
					button.addEventListener('click', async () => {
						gmc.open();
						await renderButtons();
					});
					break;
			}
		}

		// Swap the row in with one replaceChild, looked up in the same sync block: overlapping
		// calls can't double-insert, and one mutation record is one observeDOM ignores.
		const rows = [...document.querySelectorAll('.YT-HWV-BUTTONS')];
		const current = rows.find(
			(el) => el.parentNode === target.parentNode && el.nextSibling === target,
		);
		for (const el of rows) {
			if (el !== current) el.remove();
		}
		const focusAt = current
			? [...current.children].indexOf(document.activeElement)
			: -1;
		if (current) {
			target.parentNode.replaceChild(buttonArea, current);
		} else {
			target.parentNode.insertBefore(buttonArea, target);
		}
		if (focusAt > -1) buttonArea.children[focusAt]?.focus();
		logDebug('Rendered menu buttons');
	};

	const run = debounce(async (mutations) => {
		// Don't react if only our own buttons changed state
		// to avoid running an endless loop
		if (
			mutations &&
			mutations.length === 1 &&
			mutations[0].target.classList.contains('YT-HWV-BUTTON')
		) {
			return;
		}

		logDebug(
			'Running check for watched videos, shorts, mixes, members, and subs',
		);
		applySubbedTintSetting();
		await updateClassOnWatchedItems();
		await updateClassOnShortsItems();
		await updateClassOnMixesItems();
		await updateClassOnMembersItems();
		await updateClassOnSubscribedItems();
		updateClassOnPlayablesShelves();
		reflowRichGrids();
		await renderButtons();
	}, 250);

	// ===========================================================

	const observeDOM = (() => {
		const MutationObserver =
			window.MutationObserver || window.WebKitMutationObserver;
		const eventListenerSupported = window.addEventListener;

		return (obj, callback) => {
			logDebug('Attaching DOM listener');

			// Invalid `obj` given
			if (!obj) return;

			if (MutationObserver) {
				const obs = new MutationObserver((mutations, _observer) => {
					// If the mutation is the script's own buttons being injected, ignore the event
					if (
						mutations.length === 1 &&
						mutations[0].addedNodes?.length === 1 &&
						mutations[0].addedNodes[0]?.classList?.contains('YT-HWV-BUTTONS')
					) {
						return;
					}

					if (
						mutations[0].addedNodes.length ||
						mutations[0].removedNodes.length
					) {
						callback(mutations);
					}
				});

				obs.observe(obj, { childList: true, subtree: true });
			} else if (eventListenerSupported) {
				obj.addEventListener('DOMNodeInserted', callback, false);
				obj.addEventListener('DOMNodeRemoved', callback, false);
			}
		};
	})();

	// ===========================================================

	logDebug('Starting Script');

	// YouTube does navigation via history and also does a bunch
	// of AJAX video loading. In order to ensure we're always up
	// to date, we have to listen for ANY DOM change event, and
	// re-run our script.
	observeDOM(document.body, run);

	// Resizing changes how many tiles fit per row without touching the
	// DOM, so the observer above never sees it.
	window.addEventListener('resize', () => run());

	run();
})();

