(function () {
  'use strict';
  if (window.__CHAT_FIND_INSTALLED__) return;
  window.__CHAT_FIND_INSTALLED__ = true;

function createChatFindRuntime() {
  // --- core/search-engine.js ---
// Core search engine: pure pattern compiler + DOM TreeWalker block-aware matcher.

const BLOCK_TAGS = new Set([
  'ADDRESS', 'ARTICLE', 'ASIDE', 'BLOCKQUOTE', 'CAPTION', 'DD', 'DETAILS',
  'DIALOG', 'DIV', 'DL', 'DT', 'FIELDSET', 'FIGCAPTION', 'FIGURE', 'FOOTER',
  'FORM', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'HEADER', 'HGROUP', 'HR',
  'LI', 'MAIN', 'NAV', 'OL', 'P', 'PRE', 'SECTION', 'SUMMARY', 'TABLE',
  'TBODY', 'TD', 'TFOOT', 'TH', 'THEAD', 'TR', 'UL',
]);

const SKIP_TAGS = new Set([
  'SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'TEXTAREA', 'INPUT', 'SELECT',
  'OPTION', 'SVG', 'CANVAS', 'AUDIO', 'VIDEO', 'IFRAME', 'OBJECT', 'EMBED',
]);

function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function compilePattern(query, options = {}) {
  if (!query || typeof query !== 'string') {
    return { regex: null, error: null };
  }
  const caseSensitive = Boolean(options.caseSensitive);
  const wholeWord = Boolean(options.wholeWord);
  const isRegex = Boolean(options.regex);
  const flags = caseSensitive ? 'g' : 'gi';

  let source = isRegex ? query : escapeRegExp(query);
  if (wholeWord && !isRegex) {
    const startWord = /^[A-Za-z0-9_]/.test(query);
    const endWord = /[A-Za-z0-9_]$/.test(query);
    source = `${startWord ? '\\b' : ''}${source}${endWord ? '\\b' : ''}`;
  } else if (wholeWord && isRegex) {
    source = `\\b(?:${source})\\b`;
  }

  try {
    const regex = new RegExp(source, flags);
    return { regex, error: null };
  } catch (err) {
    return { regex: null, error: err instanceof Error ? err.message : String(err) };
  }
}

function findMatchesInText(text, regex, maxRemaining = 2000) {
  if (!text || !regex || maxRemaining <= 0) return { hits: [], truncated: false };
  regex.lastIndex = 0;
  const hits = [];
  let truncated = false;
  let match;
  while ((match = regex.exec(text)) !== null) {
    const len = match[0].length;
    if (len === 0) {
      regex.lastIndex += 1;
      if (regex.lastIndex > text.length) break;
      continue;
    }
    if (hits.length >= maxRemaining) {
      truncated = true;
      break;
    }
    hits.push({
      start: match.index,
      end: match.index + len,
      text: match[0],
    });
  }
  return { hits, truncated };
}

function buildContextSnippet(fullText, start, end, radius = 28) {
  const clean = (s) => s.replace(/\s+/g, ' ');
  const beforeRaw = fullText.slice(Math.max(0, start - radius), start);
  const afterRaw = fullText.slice(end, Math.min(fullText.length, end + radius));
  const before = (start > radius ? '…' : '') + clean(beforeRaw);
  const after = clean(afterRaw) + (end + radius < fullText.length ? '…' : '');
  return { before, after };
}

function getBlockAncestor(node, stopRoot) {
  let cur = node.parentElement;
  while (cur && cur !== stopRoot) {
    if (BLOCK_TAGS.has(cur.tagName)) return cur;
    cur = cur.parentElement;
  }
  return stopRoot;
}

function isElementSkipped(el, excludeSelector) {
  if (!el) return true;
  if (SKIP_TAGS.has(el.tagName)) return true;
  if (el.hidden || el.getAttribute('aria-hidden') === 'true') return true;
  if (excludeSelector && el.closest(excludeSelector)) return true;
  if (el.offsetParent === null) {
    const style = typeof getComputedStyle === 'function' ? getComputedStyle(el) : null;
    if (style && (style.display === 'none' || style.visibility === 'hidden')) return true;
    if (style && style.position !== 'fixed' && style.position !== 'sticky') {
      if (typeof el.getClientRects === 'function' && el.getClientRects().length === 0) return true;
    }
  }
  return false;
}

function resolveOffset(segments, targetOffset) {
  // Binary search over segments [{ node, start, end }]
  let lo = 0;
  let hi = segments.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const seg = segments[mid];
    if (targetOffset < seg.start) {
      hi = mid - 1;
    } else if (targetOffset >= seg.end) {
      lo = mid + 1;
    } else {
      return { node: seg.node, offset: targetOffset - seg.start };
    }
  }
  const last = segments[segments.length - 1];
  return { node: last.node, offset: last.end - last.start };
}

function resolveEndOffset(segments, targetEnd) {
  // End offset is exclusive, so targetEnd === seg.end maps to end of seg.node
  let lo = 0;
  let hi = segments.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const seg = segments[mid];
    if (targetEnd <= seg.start) {
      hi = mid - 1;
    } else if (targetEnd > seg.end) {
      lo = mid + 1;
    } else {
      return { node: seg.node, offset: targetEnd - seg.start };
    }
  }
  const last = segments[segments.length - 1];
  return { node: last.node, offset: last.end - last.start };
}

function searchDOM(roots, query, options = {}) {
  const maxMatches = options.maxMatches ?? 2000;
  const excludeSelectors = options.excludeSelectors ?? ['[data-chat-find-host]'];
  const excludeSelector = excludeSelectors.filter(Boolean).join(', ');
  const { regex, error } = compilePattern(query, options);

  if (error) {
    return { matches: [], truncated: false, error };
  }
  if (!regex || !roots || roots.length === 0) {
    return { matches: [], truncated: false, error: null };
  }

  const blockMap = new Map();
  const blockOrder = [];

  for (const root of roots) {
    if (!root || !root.isConnected) continue;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (!node.nodeValue || !node.nodeValue.trim()) {
          // Keep single spaces between inline elements inside a block if non-empty
          if (!node.nodeValue) return NodeFilter.FILTER_REJECT;
        }
        const parent = node.parentElement;
        if (!parent || isElementSkipped(parent, excludeSelector)) {
          return NodeFilter.FILTER_REJECT;
        }
        return NodeFilter.FILTER_ACCEPT;
      },
    });

    let textNode;
    while ((textNode = walker.nextNode())) {
      const blockEl = getBlockAncestor(textNode, root);
      let entry = blockMap.get(blockEl);
      if (!entry) {
        entry = { blockEl, text: '', segments: [] };
        blockMap.set(blockEl, entry);
        blockOrder.push(entry);
      }
      const val = textNode.nodeValue || '';
      const start = entry.text.length;
      const end = start + val.length;
      entry.text += val;
      entry.segments.push({ node: textNode, start, end });
    }
  }

  const matches = [];
  let truncated = false;

  for (const entry of blockOrder) {
    if (matches.length >= maxMatches) {
      truncated = true;
      break;
    }
    const remaining = maxMatches - matches.length;
    const { hits, truncated: blockTruncated } = findMatchesInText(entry.text, regex, remaining);
    if (blockTruncated) truncated = true;

    for (const hit of hits) {
      const startPos = resolveOffset(entry.segments, hit.start);
      const endPos = resolveEndOffset(entry.segments, hit.end);
      try {
        const range = document.createRange();
        range.setStart(startPos.node, startPos.offset);
        range.setEnd(endPos.node, endPos.offset);
        const snippet = buildContextSnippet(entry.text, hit.start, hit.end, 28);
        matches.push({
          index: matches.length,
          range,
          text: hit.text,
          before: snippet.before,
          after: snippet.after,
          blockEl: entry.blockEl,
        });
      } catch {
        // Ignore stale or invalid DOM range
      }
    }
  }

  return { matches, truncated, error: null };
}

  // --- core/highlighter.js ---
// Non-destructive highlighter using CSS Custom Highlight API with graceful fallback.

const HIGHLIGHT_ALL = 'chat-find-all';
const HIGHLIGHT_ACTIVE = 'chat-find-active';
const STYLE_ATTR = 'data-chat-find-style';

const HIGHLIGHT_CSS = `
::highlight(${HIGHLIGHT_ALL}) {
  background-color: rgba(250, 204, 21, 0.36);
  color: inherit;
}
::highlight(${HIGHLIGHT_ACTIVE}) {
  background-color: rgba(249, 115, 22, 0.78);
  color: #ffffff;
}
`;

function createHighlighter() {
  let styleEl = null;

  function supportsCustomHighlight() {
    return (
      typeof CSS !== 'undefined' &&
      CSS &&
      typeof CSS.highlights !== 'undefined' &&
      typeof Highlight === 'function'
    );
  }

  function ensureStyle() {
    if (styleEl && styleEl.isConnected) return;
    if (typeof document === 'undefined' || !document.head) return;
    const existing = document.head.querySelector(`style[${STYLE_ATTR}]`);
    if (existing) {
      styleEl = existing;
      return;
    }
    styleEl = document.createElement('style');
    styleEl.setAttribute(STYLE_ATTR, 'true');
    styleEl.textContent = HIGHLIGHT_CSS;
    document.head.appendChild(styleEl);
  }

  function apply(matches, activeIndex) {
    if (!supportsCustomHighlight()) return false;
    ensureStyle();
    if (!matches || matches.length === 0) {
      CSS.highlights.delete(HIGHLIGHT_ALL);
      CSS.highlights.delete(HIGHLIGHT_ACTIVE);
      return true;
    }

    const validRanges = [];
    for (const m of matches) {
      if (m && m.range && m.range.startContainer && m.range.startContainer.isConnected) {
        validRanges.push(m.range);
      }
    }

    if (validRanges.length === 0) {
      CSS.highlights.delete(HIGHLIGHT_ALL);
      CSS.highlights.delete(HIGHLIGHT_ACTIVE);
      return true;
    }

    try {
      CSS.highlights.set(HIGHLIGHT_ALL, new Highlight(...validRanges));
      const active = matches[activeIndex];
      if (active && active.range && active.range.startContainer && active.range.startContainer.isConnected) {
        CSS.highlights.set(HIGHLIGHT_ACTIVE, new Highlight(active.range));
      } else {
        CSS.highlights.delete(HIGHLIGHT_ACTIVE);
      }
      return true;
    } catch {
      return false;
    }
  }

  function scrollToMatch(match, scrollContainer) {
    if (!match || !match.range) return;
    const { range } = match;
    if (!range.startContainer || !range.startContainer.isConnected) return;

    try {
      const rect = range.getBoundingClientRect();
      if (scrollContainer && scrollContainer !== document.body && scrollContainer !== document.documentElement) {
        const containerRect = scrollContainer.getBoundingClientRect();
        const targetTop =
          scrollContainer.scrollTop +
          (rect.top - containerRect.top) -
          scrollContainer.clientHeight * 0.38;
        scrollContainer.scrollTo({
          top: Math.max(0, targetTop),
          behavior: 'smooth',
        });
      } else {
        const anchor = range.startContainer.parentElement || match.blockEl;
        if (anchor && typeof anchor.scrollIntoView === 'function') {
          anchor.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'smooth' });
        }
      }
    } catch {
      // Fallback: ignore scroll error on detached nodes
    }

    // Fallback selection flash only when CSS Custom Highlight API is unavailable
    if (!supportsCustomHighlight()) {
      try {
        const sel = window.getSelection();
        if (sel) {
          sel.removeAllRanges();
          sel.addRange(range.cloneRange());
        }
      } catch {
        // Ignore selection errors
      }
    }
  }

  function clear() {
    if (supportsCustomHighlight()) {
      try {
        CSS.highlights.delete(HIGHLIGHT_ALL);
        CSS.highlights.delete(HIGHLIGHT_ACTIVE);
      } catch {
        // Ignore cleanup errors
      }
    }
  }

  function dispose() {
    clear();
    if (styleEl && styleEl.parentNode) {
      styleEl.parentNode.removeChild(styleEl);
    }
    styleEl = null;
  }

  return {
    supportsCustomHighlight,
    apply,
    scrollToMatch,
    clear,
    dispose,
  };
}

  // --- core/scope-resolver.js ---
// Smart scope resolver: identifies conversation container in DSH, Codex, Antigravity, and generic web apps.

const CHAT_SELECTORS = [
  '[data-conversation-scroll]',
  '[data-conversation-content]',
  '[data-testid="conversation-turns"]',
  '[data-testid="conversation-panel"]',
  'main [role="log"]',
  'main',
  '[role="main"]',
  '.conversation-container',
  '.chat-messages',
];

function isScrollable(el) {
  if (!el || el === document.body || el === document.documentElement) return false;
  try {
    const style = getComputedStyle(el);
    const overflowY = style.overflowY;
    return (
      (overflowY === 'auto' || overflowY === 'scroll' || overflowY === 'overlay') &&
      el.scrollHeight > el.clientHeight + 4
    );
  } catch {
    return false;
  }
}

function findScrollContainer(el) {
  if (!el) return null;
  if (isScrollable(el)) return el;
  let cur = el.parentElement;
  while (cur && cur !== document.body && cur !== document.documentElement) {
    if (isScrollable(cur)) return cur;
    cur = cur.parentElement;
  }
  return el.scrollHeight > el.clientHeight ? el : null;
}

function detectSessionKey() {
  const conv = document.querySelector('[data-conversation-session]');
  if (conv) {
    return conv.getAttribute('data-conversation-session') || '';
  }
  return `${location.pathname}${location.search}${location.hash}`;
}

function resolveScope(scopeMode = 'chat', adapterHint = 'generic') {
  const baseExclude = ['[data-chat-find-host]'];
  const sessionKey = detectSessionKey();

  if (scopeMode === 'page') {
    return {
      roots: document.body ? [document.body] : [],
      scrollContainer: findScrollContainer(document.querySelector('[data-conversation-scroll]')) || document.scrollingElement || document.documentElement,
      excludeSelectors: baseExclude,
      sessionKey,
      resolvedAs: 'page',
    };
  }

  // Chat scope: prioritize DSH conversation scroll container
  if (adapterHint === 'dsh') {
    const dshScroll = document.querySelector('[data-conversation-scroll]');
    if (dshScroll) {
      return {
        roots: [dshScroll],
        scrollContainer: dshScroll,
        excludeSelectors: [...baseExclude, '[data-composer-seat]', '[data-conversation-region="composer"]'],
        sessionKey,
        resolvedAs: 'chat',
      };
    }
  }

  for (const selector of CHAT_SELECTORS) {
    const candidate = document.querySelector(selector);
    if (candidate && candidate.innerText && candidate.innerText.trim().length > 0) {
      return {
        roots: [candidate],
        scrollContainer: findScrollContainer(candidate) || document.scrollingElement || document.documentElement,
        excludeSelectors: [
          ...baseExclude,
          '[data-composer-seat]',
          '[data-conversation-region="composer"]',
          'nav',
          'aside',
          'form',
          '[contenteditable="true"]',
        ],
        sessionKey,
        resolvedAs: 'chat',
      };
    }
  }

  // Fallback to full page when no conversation container is mounted (e.g., Settings / Plugins view)
  return {
    roots: document.body ? [document.body] : [],
    scrollContainer: document.scrollingElement || document.documentElement,
    excludeSelectors: baseExclude,
    sessionKey,
    resolvedAs: 'page',
  };
}

  // --- core/live-observer.js ---
// Debounced MutationObserver for streaming output and session switches.

function createLiveObserver(onChange, debounceMs = 250) {
  let observer = null;
  let timer = null;
  let running = false;

  function isOwnMutation(record) {
    const target = record.target;
    if (target instanceof Element) {
      if (target.closest('[data-chat-find-host]') || target.hasAttribute('data-chat-find-style')) {
        return true;
      }
    } else if (target && target.parentElement) {
      if (target.parentElement.closest('[data-chat-find-host]')) {
        return true;
      }
    }
    return false;
  }

  function schedule() {
    if (!running) return;
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (running) onChange();
    }, debounceMs);
  }

  function start(targetEl) {
    stop();
    if (typeof MutationObserver === 'undefined') return;
    const root = targetEl || document.body;
    if (!root) return;
    running = true;
    observer = new MutationObserver((records) => {
      for (const rec of records) {
        if (!isOwnMutation(rec)) {
          schedule();
          break;
        }
      }
    });
    try {
      observer.observe(root, {
        childList: true,
        subtree: true,
        characterData: true,
        attributes: true,
        attributeFilter: ['data-conversation-session'],
      });
    } catch {
      running = false;
    }
  }

  function stop() {
    running = false;
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    if (observer) {
      observer.disconnect();
      observer = null;
    }
  }

  return {
    start,
    stop,
    isRunning: () => running,
  };
}

  // --- core/minimap-markers.js ---
// Computes normalized vertical marker positions for the right-edge minimap scrollbar track.

function computeMinimapMarkers(matches, activeIndex, scrollContainer, maxMarkers = 200) {
  if (!matches || matches.length === 0) return [];

  const isDocScroll =
    !scrollContainer ||
    scrollContainer === document.body ||
    scrollContainer === document.documentElement;

  const containerRect = isDocScroll
    ? { top: 0, height: window.innerHeight || 1 }
    : scrollContainer.getBoundingClientRect();

  const scrollTop = isDocScroll
    ? window.scrollY || document.documentElement.scrollTop || 0
    : scrollContainer.scrollTop;

  const scrollHeight = Math.max(
    1,
    isDocScroll
      ? document.documentElement.scrollHeight || document.body.scrollHeight || 1
      : scrollContainer.scrollHeight
  );

  const raw = [];
  for (let i = 0; i < matches.length; i++) {
    const m = matches[i];
    if (!m || !m.range || !m.range.startContainer || !m.range.startContainer.isConnected) continue;
    try {
      const rect = m.range.getBoundingClientRect();
      if (rect.width === 0 && rect.height === 0 && rect.top === 0) continue;
      const absTop = isDocScroll
        ? rect.top + scrollTop
        : rect.top - containerRect.top + scrollTop;
      const ratio = Math.min(1, Math.max(0, absTop / scrollHeight));
      raw.push({ index: i, ratio, active: i === activeIndex });
    } catch {
      // Skip detached ranges
    }
  }

  if (raw.length <= maxMarkers) return raw;

  // Bucket into maxMarkers slots while preserving active marker
  const buckets = new Map();
  let activeMarker = null;
  for (const item of raw) {
    if (item.active) {
      activeMarker = item;
      continue;
    }
    const bucket = Math.round(item.ratio * (maxMarkers - 1));
    if (!buckets.has(bucket)) {
      buckets.set(bucket, item);
    }
  }
  const result = Array.from(buckets.values());
  if (activeMarker) result.push(activeMarker);
  return result;
}

