        e.preventDefault();
        e.stopPropagation();
        if (e.shiftKey) callbacks.onPrev();
        else callbacks.onNext();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        callbacks.onClose();
      } else if (e.altKey && !e.ctrlKey && !e.metaKey) {
        const k = e.key.toLowerCase();
        if (k === 'c') { e.preventDefault(); callbacks.onToggleOption('caseSensitive'); }
        else if (k === 'w') { e.preventDefault(); callbacks.onToggleOption('wholeWord'); }
        else if (k === 'r') { e.preventDefault(); callbacks.onToggleOption('regex'); }
      }
    });

    btnCase.addEventListener('click', () => callbacks.onToggleOption('caseSensitive'));
    btnWord.addEventListener('click', () => callbacks.onToggleOption('wholeWord'));
    btnRegex.addEventListener('click', () => callbacks.onToggleOption('regex'));
    btnScope.addEventListener('click', () => callbacks.onToggleScope());
    btnCount.addEventListener('click', () => {
      expanded = !expanded;
      listWrapEl.setAttribute('data-expanded', String(expanded));
      callbacks.onExpandChange(expanded);
    });
    btnPrev.addEventListener('click', () => callbacks.onPrev());
    btnNext.addEventListener('click', () => callbacks.onNext());
    btnClose.addEventListener('click', () => callbacks.onClose());

    applyLocaleStrings('chat');
  }

  function applyLocaleStrings(scopeMode) {
    if (!inputEl) return;
    const t = getMessages(lang);
    inputEl.placeholder = scopeMode === 'page' ? t.placeholderPage : t.placeholder;
    btnCase.title = t.caseSensitive;
    btnWord.title = t.wholeWord;
    btnRegex.title = t.regex;
    btnScope.textContent = scopeMode === 'page' ? t.scopePage : t.scopeChat;
    btnScope.title = scopeMode === 'page' ? t.scopePageTitle : t.scopeChatTitle;
    btnCount.title = t.listToggle;
    btnPrev.title = t.prev;
    btnNext.title = t.next;
    btnClose.title = t.close;
  }

  function mount(parentContainer) {
    if (!hostEl) buildDOM();
    const target = parentContainer || document.body;
    if (target && hostEl.parentNode !== target) {
      target.appendChild(hostEl);
    }
    return hostEl;
  }

  function render(state) {
    if (!panelEl) return;
    const t = getMessages(lang);
    panelEl.setAttribute('data-open', String(state.open));

    if (inputEl.value !== state.query) {
      inputEl.value = state.query;
    }

    btnCase.setAttribute('data-active', String(state.caseSensitive));
    btnWord.setAttribute('data-active', String(state.wholeWord));
    btnRegex.setAttribute('data-active', String(state.regex));
    btnScope.setAttribute('data-active', String(state.scope === 'page'));
    applyLocaleStrings(state.scope);

    // Error state
    const hasError = Boolean(state.error);
    inputWrapEl.setAttribute('data-error', String(hasError));
    errorEl.setAttribute('data-visible', String(hasError));
    errorEl.textContent = hasError ? `${t.regexError}: ${state.error}` : '';

    // Count & navigation buttons
    const total = state.matches.length;
    const hasHits = total > 0;
    const totalLabel = state.truncated ? `${total}+` : `${total}`;
    const caret = expanded ? ' ▴' : ' ▾';
    if (!state.query) {
      btnCount.textContent = `0 / 0`;
    } else if (!hasHits) {
      btnCount.textContent = t.noResults;
    } else {
      btnCount.textContent = `${state.activeIndex + 1} / ${totalLabel}${caret}`;
    }
    btnCount.setAttribute('data-has-hits', String(hasHits));
    btnPrev.disabled = !hasHits;
    btnNext.disabled = !hasHits;

    // Expandable hit list
    listWrapEl.setAttribute('data-expanded', String(state.open && expanded && Boolean(state.query)));
    if (state.open && expanded && state.query) {
      renderHitList(state, t);
    }

    // Minimap markers
    renderMinimap(state);
  }

  function renderHitList(state, t) {
    listWrapEl.textContent = '';
    if (state.matches.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'cf-list-empty';
      empty.textContent = t.emptyList;
      listWrapEl.appendChild(empty);
      return;
    }

    const frag = document.createDocumentFragment();
    const limit = Math.min(state.matches.length, 300);
    for (let i = 0; i < limit; i++) {
      const m = state.matches[i];
      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'cf-list-item';
      item.setAttribute('data-active', String(i === state.activeIndex));

      const num = document.createElement('span');
      num.className = 'cf-item-num';
      num.textContent = String(i + 1);

      const snippet = document.createElement('span');
      snippet.className = 'cf-item-snippet';
      if (m.before) snippet.appendChild(document.createTextNode(m.before));
      const hit = document.createElement('span');
      hit.className = 'cf-item-hit';
      hit.textContent = m.text;
      snippet.appendChild(hit);
      if (m.after) snippet.appendChild(document.createTextNode(m.after));

      item.append(num, snippet);
      item.addEventListener('click', () => callbacks.onJumpTo(i));
      frag.appendChild(item);
    }

    if (state.matches.length > limit || state.truncated) {
      const note = document.createElement('div');
      note.className = 'cf-list-note';
      note.textContent = t.truncatedHint.replace('{n}', String(limit));
      frag.appendChild(note);
    }

    listWrapEl.appendChild(frag);

    // Keep active item visible inside dropdown
    const activeItem = listWrapEl.querySelector('.cf-list-item[data-active="true"]');
    if (activeItem && typeof activeItem.scrollIntoView === 'function') {
      activeItem.scrollIntoView({ block: 'nearest' });
    }
  }

  function renderMinimap(state) {
    if (!minimapEl) return;
    const markers = state.markers || [];
    const visible = state.open && markers.length > 0;
    minimapEl.setAttribute('data-visible', String(visible));
    minimapEl.textContent = '';
    if (!visible) return;

    const frag = document.createDocumentFragment();
    for (const mk of markers) {
      const dot = document.createElement('div');
      dot.className = 'cf-marker';
      dot.style.top = `${(mk.ratio * 100).toFixed(2)}%`;
      if (mk.active) dot.setAttribute('data-active', 'true');
      dot.addEventListener('click', () => callbacks.onJumpTo(mk.index));
      frag.appendChild(dot);
    }
    minimapEl.appendChild(frag);
  }

  function focusInput(selectAll = true) {
    if (!inputEl) return;
    requestAnimationFrame(() => {
      try {
        inputEl.focus({ preventScroll: true });
        if (selectAll) inputEl.select();
      } catch {
        // Ignore focus errors
      }
    });
  }

  function setLocale(nextLang) {
    lang = nextLang || 'en';
  }

  function setExpanded(value) {
    expanded = Boolean(value);
  }

  function dispose() {
    if (hostEl && hostEl.parentNode) {
      hostEl.parentNode.removeChild(hostEl);
    }
    hostEl = null;
    shadow = null;
    panelEl = null;
  }

  return {
    mount,
    render,
    focusInput,
    setLocale,
    setExpanded,
    dispose,
    getHostElement: () => hostEl,
  };
}

  // --- core/index.js ---
// Unified ChatFind controller coordinating search, highlighting, scope, live sync, minimap, and UI.







function createChatFindController(options = {}) {
  const adapterHint = options.adapterHint || 'generic';
  const initialLocale = options.locale || (typeof navigator !== 'undefined' ? navigator.language : 'en');
  const maxMatches = options.maxMatches ?? 2000;

  const highlighter = createHighlighter();

  const state = {
    open: false,
    query: '',
    caseSensitive: false,
    wholeWord: false,
    regex: false,
    scope: 'chat',
    matches: [],
    truncated: false,
    error: null,
    activeIndex: -1,
    markers: [],
  };

  let lastFocusEl = null;
  let currentScrollContainer = null;
  let lastSessionKey = '';
  let resizeTimer = null;
  let disposed = false;

  const ui = createOverlayUI(
    {
      onQueryChange(nextQuery) {
        state.query = nextQuery;
        runSearch({ scrollToActive: true, resetIndex: true });
      },
      onToggleOption(key) {
        state[key] = !state[key];
        runSearch({ scrollToActive: true, resetIndex: true });
      },
      onToggleScope() {
        state.scope = state.scope === 'chat' ? 'page' : 'chat';
        runSearch({ scrollToActive: true, resetIndex: true });
      },
      onNext() {
        next();
      },
      onPrev() {
        prev();
      },
      onJumpTo(index) {
        jumpTo(index);
      },
      onExpandChange() {
        ui.render(state);
      },
      onClose() {
        close();
      },
    },
    initialLocale
  );

  const liveObserver = createLiveObserver(() => {
    if (!state.open || !state.query) return;
    runSearch({ scrollToActive: false, resetIndex: false });
  }, 250);

  function getSelectedShortText() {
    try {
      const sel = window.getSelection();
      if (!sel || sel.isCollapsed) return '';
      const text = sel.toString().trim();
      if (!text || text.length > 80 || /[\r\n]/.test(text)) return '';
      return text;
    } catch {
      return '';
    }
  }

  function runSearch({ scrollToActive = false, resetIndex = false } = {}) {
    if (disposed) return;
    const scopeInfo = resolveScope(state.scope, adapterHint);
    currentScrollContainer = scopeInfo.scrollContainer;

    const sessionChanged = Boolean(lastSessionKey && scopeInfo.sessionKey !== lastSessionKey);
    lastSessionKey = scopeInfo.sessionKey;

    if (!state.query) {
      state.matches = [];
      state.truncated = false;
      state.error = null;
      state.activeIndex = -1;
      state.markers = [];
      highlighter.clear();
      liveObserver.stop();
      ui.render(state);
      return;
    }

    const result = searchDOM(scopeInfo.roots, state.query, {
      caseSensitive: state.caseSensitive,
      wholeWord: state.wholeWord,
      regex: state.regex,
      maxMatches,
      excludeSelectors: scopeInfo.excludeSelectors,
    });

    state.matches = result.matches;
    state.truncated = result.truncated;
    state.error = result.error;

    if (state.matches.length === 0) {
      state.activeIndex = -1;
    } else if (resetIndex || sessionChanged || state.activeIndex < 0) {
      state.activeIndex = 0;
    } else if (state.activeIndex >= state.matches.length) {
      state.activeIndex = state.matches.length - 1;
    }

    highlighter.apply(state.matches, state.activeIndex);
    state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
    ui.render(state);

    if (scrollToActive && state.activeIndex >= 0 && state.matches[state.activeIndex]) {
      highlighter.scrollToMatch(state.matches[state.activeIndex], currentScrollContainer);
    }

    // Keep live observer running while open with active query
    if (state.open && state.query) {
      liveObserver.start(document.body);
    }
  }

  function open(initialQuery) {
    if (disposed) return;
    if (!state.open) {
      lastFocusEl = document.activeElement instanceof HTMLElement ? document.activeElement : null;
      state.open = true;
    }
    const candidate = typeof initialQuery === 'string' ? initialQuery : getSelectedShortText();
    if (candidate) {
      state.query = candidate;
    }
    ui.mount(options.mountContainer);
    runSearch({ scrollToActive: Boolean(candidate), resetIndex: Boolean(candidate) });
    ui.focusInput(true);
  }

  function close() {
    if (disposed || !state.open) return;
    state.open = false;
    state.markers = [];
    ui.setExpanded(false);
    liveObserver.stop();
    highlighter.clear();
    ui.render(state);
    if (lastFocusEl && lastFocusEl.isConnected) {
      try {
        lastFocusEl.focus({ preventScroll: true });
      } catch {
        // Ignore focus restoration error
      }
    }
    lastFocusEl = null;
  }

  function next() {
    if (!state.open || state.matches.length === 0) return;
    state.activeIndex = (state.activeIndex + 1) % state.matches.length;
    highlighter.apply(state.matches, state.activeIndex);
    state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
    ui.render(state);
    highlighter.scrollToMatch(state.matches[state.activeIndex], currentScrollContainer);
  }

  function prev() {
    if (!state.open || state.matches.length === 0) return;
    state.activeIndex = (state.activeIndex - 1 + state.matches.length) % state.matches.length;
    highlighter.apply(state.matches, state.activeIndex);
    state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
    ui.render(state);
    highlighter.scrollToMatch(state.matches[state.activeIndex], currentScrollContainer);
  }

  function jumpTo(index) {
    if (!state.open || index < 0 || index >= state.matches.length) return;
    state.activeIndex = index;
    highlighter.apply(state.matches, state.activeIndex);
    state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
    ui.render(state);
    highlighter.scrollToMatch(state.matches[state.activeIndex], currentScrollContainer);
  }

  function isTargetInTerminal(target) {
    return target instanceof Element && Boolean(target.closest('.xterm'));
  }

  function hasBlockingModal() {
    const modals = document.querySelectorAll('[role="dialog"][aria-modal="true"]');
    return modals.length > 0;
  }

  function handleKeyDown(e) {
    if (disposed) return;
    const isPrimary = (e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey;
    const isFindKey = isPrimary && (e.code === 'KeyF' || e.key.toLowerCase() === 'f');

    if (isFindKey) {
      if (isTargetInTerminal(e.target)) return;
      if (!state.open && hasBlockingModal()) return;
      e.preventDefault();
      e.stopPropagation();
      open();
      return;
    }

    if (state.open && e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      close();
    }
  }

  function handleResize() {
    if (!state.open || state.matches.length === 0) return;
    if (resizeTimer !== null) clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      resizeTimer = null;
      if (!disposed && state.open && state.matches.length > 0) {
        state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
        ui.render(state);
      }
    }, 150);
  }

  function attachGlobalListeners() {
    window.addEventListener('keydown', handleKeyDown, true);
    window.addEventListener('resize', handleResize);
  }

  function detachGlobalListeners() {
    window.removeEventListener('keydown', handleKeyDown, true);
    window.removeEventListener('resize', handleResize);
  }

  function mount(container) {
    if (container) options.mountContainer = container;
    ui.mount(options.mountContainer);
    attachGlobalListeners();
  }

  function setLocale(lang) {
    ui.setLocale(lang);
    ui.render(state);
  }

  function dispose() {
    disposed = true;
    if (resizeTimer !== null) {
      clearTimeout(resizeTimer);
      resizeTimer = null;
    }
    detachGlobalListeners();
    liveObserver.stop();
    highlighter.dispose();
    ui.dispose();
  }

  return {
    mount,
    open,
    close,
    toggle: () => (state.open ? close() : open()),
    isOpen: () => state.open,
    next,
    prev,
    jumpTo,
    refresh: () => runSearch({ scrollToActive: false, resetIndex: false }),
    setLocale,
    dispose,
  };
}
  return { createChatFindController };
}

  const { createChatFindController } = createChatFindRuntime();
  const controller = createChatFindController({
    adapterHint: 'generic',
    locale: navigator.language || 'en',
  });
  controller.mount(document.body);
  window.__CHAT_FIND_CONTROLLER__ = controller;
})();

