      document.body.appendChild(mask);

      let scale = 1,
        tx = 0,
        ty = 0,
        rafId = null;
      let images = [],
        currentIdx = 0,
        clickTimer = null;

      const reset = () => {
        scale = 1;
        tx = ty = 0;
        container.style.transform = "translate(0px,0px) scale(1)";
        img.classList.remove("loaded");
