      const download = () => {
        const url = img.src;
        const name = url.split("/").pop().split("?")[0] || "github-image.png";
        fetch(url)
          .then((r) => r.blob())
          .then((blob) => {
            const a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            a.download = name;
            a.click();
            URL.revokeObjectURL(a.href);
