            if (loc && typeof loc.getSnapshot === 'function') {
              const snap = loc.getSnapshot();
              if (snap && snap.active) return snap.active;
            }
          } catch {}
          return typeof navigator !== 'undefined' ? navigator.language : 'en';
        };

        currentLocale = resolveLocale();

        ctx.effect(() => {
          const loc = ctx.get && ctx.get('locale');
          if (!loc || typeof loc.subscribe !== 'function') return;
          return loc.subscribe(() => {
            currentLocale = resolveLocale();
            if (activeController) activeController.setLocale(currentLocale);
          });
        }, 'dsh-chat-find: locale sync');

        ctx.effect(() => {
          const shortcuts = ctx.get && ctx.get('shortcuts');
          if (!shortcuts || typeof shortcuts.register !== 'function') return;
          try {
            return shortcuts.register({
              id: 'dsh-chat-find.open',
