// Non-destructive highlighter using CSS Custom Highlight API with graceful fallback.

const HIGHLIGHT_ALL = 'chat-find-all';
const HIGHLIGHT_ACTIVE = 'chat-find-active';
const STYLE_ATTR = 'data-chat-find-style';

const HIGHLIGHT_CSS = `
::highlight(${HIGHLIGHT_ALL}) {
  background-color: rgba(250, 204, 21, 0.36);
  color: inherit;
}
::highlight(${HIGHLIGHT_ACTIVE}) {
  background-color: rgba(249, 115, 22, 0.78);
  color: #ffffff;
}
`;

export function createHighlighter() {
  let styleEl = null;

  function supportsCustomHighlight() {
    return (
      typeof CSS !== 'undefined' &&
      CSS &&
      typeof CSS.highlights !== 'undefined' &&
      typeof Highlight === 'function'
    );
  }

  function ensureStyle() {
    if (styleEl && styleEl.isConnected) return;
    if (typeof document === 'undefined' || !document.head) return;
    const existing = document.head.querySelector(`style[${STYLE_ATTR}]`);
    if (existing) {
      styleEl = existing;
      return;
    }
    styleEl = document.createElement('style');
    styleEl.setAttribute(STYLE_ATTR, 'true');
    styleEl.textContent = HIGHLIGHT_CSS;
    document.head.appendChild(styleEl);
  }

  function apply(matches, activeIndex) {
    if (!supportsCustomHighlight()) return false;
    ensureStyle();
    if (!matches || matches.length === 0) {
      CSS.highlights.delete(HIGHLIGHT_ALL);
      CSS.highlights.delete(HIGHLIGHT_ACTIVE);
      return true;
    }

    const validRanges = [];
    for (const m of matches) {
      if (m && m.range && m.range.startContainer && m.range.startContainer.isConnected) {
        validRanges.push(m.range);
      }
    }

    if (validRanges.length === 0) {
      CSS.highlights.delete(HIGHLIGHT_ALL);
      CSS.highlights.delete(HIGHLIGHT_ACTIVE);
      return true;
    }

    try {
      CSS.highlights.set(HIGHLIGHT_ALL, new Highlight(...validRanges));
      const active = matches[activeIndex];
      if (active && active.range && active.range.startContainer && active.range.startContainer.isConnected) {
        CSS.highlights.set(HIGHLIGHT_ACTIVE, new Highlight(active.range));
      } else {
        CSS.highlights.delete(HIGHLIGHT_ACTIVE);
      }
      return true;
    } catch {
      return false;
    }
  }

  function scrollToMatch(match, scrollContainer) {
    if (!match || !match.range) return;
    const { range } = match;
    if (!range.startContainer || !range.startContainer.isConnected) return;

    try {
      const rect = range.getBoundingClientRect();
      if (scrollContainer && scrollContainer !== document.body && scrollContainer !== document.documentElement) {
        const containerRect = scrollContainer.getBoundingClientRect();
        const targetTop =
          scrollContainer.scrollTop +
          (rect.top - containerRect.top) -
          scrollContainer.clientHeight * 0.38;
        scrollContainer.scrollTo({
          top: Math.max(0, targetTop),
          behavior: 'smooth',
        });
      } else {
        const anchor = range.startContainer.parentElement || match.blockEl;
        if (anchor && typeof anchor.scrollIntoView === 'function') {
          anchor.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'smooth' });
        }
      }
    } catch {
      // Fallback: ignore scroll error on detached nodes
    }

    // Fallback selection flash only when CSS Custom Highlight API is unavailable
    if (!supportsCustomHighlight()) {
      try {
        const sel = window.getSelection();
        if (sel) {
          sel.removeAllRanges();
          sel.addRange(range.cloneRange());
        }
      } catch {
        // Ignore selection errors
      }
    }
  }

  function clear() {
    if (supportsCustomHighlight()) {
      try {
        CSS.highlights.delete(HIGHLIGHT_ALL);
        CSS.highlights.delete(HIGHLIGHT_ACTIVE);
      } catch {
        // Ignore cleanup errors
      }
    }
  }

  function dispose() {
    clear();
    if (styleEl && styleEl.parentNode) {
      styleEl.parentNode.removeChild(styleEl);
    }
    styleEl = null;
  }

  return {
    supportsCustomHighlight,
    apply,
    scrollToMatch,
    clear,
    dispose,
  };
}

