// Unified ChatFind controller coordinating search, highlighting, scope, live sync, minimap, and UI.

import { searchDOM } from './search-engine.js';
import { createHighlighter } from './highlighter.js';
import { resolveScope } from './scope-resolver.js';
import { createLiveObserver } from './live-observer.js';
import { computeMinimapMarkers } from './minimap-markers.js';
import { createOverlayUI } from './overlay-ui.js';

export function createChatFindController(options = {}) {
  const adapterHint = options.adapterHint || 'generic';
  const initialLocale = options.locale || (typeof navigator !== 'undefined' ? navigator.language : 'en');
  const maxMatches = options.maxMatches ?? 2000;

  const highlighter = createHighlighter();

  const state = {
    open: false,
    query: '',
    caseSensitive: false,
    wholeWord: false,
    regex: false,
    scope: 'chat',
    matches: [],
    truncated: false,
    error: null,
    activeIndex: -1,
    markers: [],
  };

  let lastFocusEl = null;
  let currentScrollContainer = null;
  let lastSessionKey = '';
  let resizeTimer = null;
  let disposed = false;

  const ui = createOverlayUI(
    {
      onQueryChange(nextQuery) {
        state.query = nextQuery;
        runSearch({ scrollToActive: true, resetIndex: true });
      },
      onToggleOption(key) {
        state[key] = !state[key];
        runSearch({ scrollToActive: true, resetIndex: true });
      },
      onToggleScope() {
        state.scope = state.scope === 'chat' ? 'page' : 'chat';
        runSearch({ scrollToActive: true, resetIndex: true });
      },
      onNext() {
        next();
      },
      onPrev() {
        prev();
      },
      onJumpTo(index) {
        jumpTo(index);
      },
      onExpandChange() {
        ui.render(state);
      },
      onClose() {
        close();
      },
    },
    initialLocale
  );

  const liveObserver = createLiveObserver(() => {
    if (!state.open || !state.query) return;
    runSearch({ scrollToActive: false, resetIndex: false });
  }, 250);

  function getSelectedShortText() {
    try {
      const sel = window.getSelection();
      if (!sel || sel.isCollapsed) return '';
      const text = sel.toString().trim();
      if (!text || text.length > 80 || /[\r\n]/.test(text)) return '';
      return text;
    } catch {
      return '';
    }
  }

  function runSearch({ scrollToActive = false, resetIndex = false } = {}) {
    if (disposed) return;
    const scopeInfo = resolveScope(state.scope, adapterHint);
    currentScrollContainer = scopeInfo.scrollContainer;

    const sessionChanged = Boolean(lastSessionKey && scopeInfo.sessionKey !== lastSessionKey);
    lastSessionKey = scopeInfo.sessionKey;

    if (!state.query) {
      state.matches = [];
      state.truncated = false;
      state.error = null;
      state.activeIndex = -1;
      state.markers = [];
      highlighter.clear();
      liveObserver.stop();
      ui.render(state);
      return;
    }

    const result = searchDOM(scopeInfo.roots, state.query, {
      caseSensitive: state.caseSensitive,
      wholeWord: state.wholeWord,
      regex: state.regex,
      maxMatches,
      excludeSelectors: scopeInfo.excludeSelectors,
    });

    state.matches = result.matches;
    state.truncated = result.truncated;
    state.error = result.error;

    if (state.matches.length === 0) {
      state.activeIndex = -1;
    } else if (resetIndex || sessionChanged || state.activeIndex < 0) {
      state.activeIndex = 0;
    } else if (state.activeIndex >= state.matches.length) {
      state.activeIndex = state.matches.length - 1;
    }

    highlighter.apply(state.matches, state.activeIndex);
    state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
    ui.render(state);

    if (scrollToActive && state.activeIndex >= 0 && state.matches[state.activeIndex]) {
      highlighter.scrollToMatch(state.matches[state.activeIndex], currentScrollContainer);
    }

    // Keep live observer running while open with active query
    if (state.open && state.query) {
      liveObserver.start(document.body);
    }
  }

  function open(initialQuery) {
    if (disposed) return;
    if (!state.open) {
      lastFocusEl = document.activeElement instanceof HTMLElement ? document.activeElement : null;
      state.open = true;
    }
    const candidate = typeof initialQuery === 'string' ? initialQuery : getSelectedShortText();
    if (candidate) {
      state.query = candidate;
    }
    ui.mount(options.mountContainer);
    runSearch({ scrollToActive: Boolean(candidate), resetIndex: Boolean(candidate) });
    ui.focusInput(true);
  }

  function close() {
    if (disposed || !state.open) return;
    state.open = false;
    state.markers = [];
    ui.setExpanded(false);
    liveObserver.stop();
    highlighter.clear();
    ui.render(state);
    if (lastFocusEl && lastFocusEl.isConnected) {
      try {
        lastFocusEl.focus({ preventScroll: true });
      } catch {
        // Ignore focus restoration error
      }
    }
    lastFocusEl = null;
  }

  function next() {
    if (!state.open || state.matches.length === 0) return;
    state.activeIndex = (state.activeIndex + 1) % state.matches.length;
    highlighter.apply(state.matches, state.activeIndex);
    state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
    ui.render(state);
    highlighter.scrollToMatch(state.matches[state.activeIndex], currentScrollContainer);
  }

  function prev() {
    if (!state.open || state.matches.length === 0) return;
    state.activeIndex = (state.activeIndex - 1 + state.matches.length) % state.matches.length;
    highlighter.apply(state.matches, state.activeIndex);
    state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
    ui.render(state);
    highlighter.scrollToMatch(state.matches[state.activeIndex], currentScrollContainer);
  }

  function jumpTo(index) {
    if (!state.open || index < 0 || index >= state.matches.length) return;
    state.activeIndex = index;
    highlighter.apply(state.matches, state.activeIndex);
    state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
    ui.render(state);
    highlighter.scrollToMatch(state.matches[state.activeIndex], currentScrollContainer);
  }

  function isTargetInTerminal(target) {
    return target instanceof Element && Boolean(target.closest('.xterm'));
  }

  function hasBlockingModal() {
    const modals = document.querySelectorAll('[role="dialog"][aria-modal="true"]');
    return modals.length > 0;
  }

  function handleKeyDown(e) {
    if (disposed) return;
    const isPrimary = (e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey;
    const isFindKey = isPrimary && (e.code === 'KeyF' || e.key.toLowerCase() === 'f');

    if (isFindKey) {
      if (isTargetInTerminal(e.target)) return;
      if (!state.open && hasBlockingModal()) return;
      e.preventDefault();
      e.stopPropagation();
      open();
      return;
    }

    if (state.open && e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      close();
    }
  }

  function handleResize() {
    if (!state.open || state.matches.length === 0) return;
    if (resizeTimer !== null) clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      resizeTimer = null;
      if (!disposed && state.open && state.matches.length > 0) {
        state.markers = computeMinimapMarkers(state.matches, state.activeIndex, currentScrollContainer);
        ui.render(state);
      }
    }, 150);
  }

  function attachGlobalListeners() {
    window.addEventListener('keydown', handleKeyDown, true);
    window.addEventListener('resize', handleResize);
  }

  function detachGlobalListeners() {
    window.removeEventListener('keydown', handleKeyDown, true);
    window.removeEventListener('resize', handleResize);
  }

  function mount(container) {
    if (container) options.mountContainer = container;
    ui.mount(options.mountContainer);
    attachGlobalListeners();
  }

  function setLocale(lang) {
    ui.setLocale(lang);
    ui.render(state);
  }

  function dispose() {
    disposed = true;
    if (resizeTimer !== null) {
      clearTimeout(resizeTimer);
      resizeTimer = null;
    }
    detachGlobalListeners();
    liveObserver.stop();
    highlighter.dispose();
    ui.dispose();
  }

  return {
    mount,
    open,
    close,
    toggle: () => (state.open ? close() : open()),
    isOpen: () => state.open,
    next,
    prev,
    jumpTo,
    refresh: () => runSearch({ scrollToActive: false, resetIndex: false }),
    setLocale,
    dispose,
  };
}

