// Debounced MutationObserver for streaming output and session switches.

export function createLiveObserver(onChange, debounceMs = 250) {
  let observer = null;
  let timer = null;
  let running = false;

  function isOwnMutation(record) {
    const target = record.target;
    if (target instanceof Element) {
      if (target.closest('[data-chat-find-host]') || target.hasAttribute('data-chat-find-style')) {
        return true;
      }
    } else if (target && target.parentElement) {
      if (target.parentElement.closest('[data-chat-find-host]')) {
        return true;
      }
    }
    return false;
  }

  function schedule() {
    if (!running) return;
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (running) onChange();
    }, debounceMs);
  }

  function start(targetEl) {
    stop();
    if (typeof MutationObserver === 'undefined') return;
    const root = targetEl || document.body;
    if (!root) return;
    running = true;
    observer = new MutationObserver((records) => {
      for (const rec of records) {
        if (!isOwnMutation(rec)) {
          schedule();
          break;
        }
      }
    });
    try {
      observer.observe(root, {
        childList: true,
        subtree: true,
        characterData: true,
        attributes: true,
        attributeFilter: ['data-conversation-session'],
      });
    } catch {
      running = false;
    }
  }

  function stop() {
    running = false;
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    if (observer) {
      observer.disconnect();
      observer = null;
    }
  }

  return {
    start,
    stop,
    isRunning: () => running,
  };
}
